window.DQW={"p-birth":{"steps":[{"h":"Choose your weapon: the <a href=\"#gear/weapon-cobblestone-greatsword\">Cobblestone Greatsword<\/a> for more damage or the <a href=\"#gear/weapon-cobblestone-sword\">Cobblestone Sword<\/a> if you want a shield.","s":[0]},{"h":"Talk to Dunstan, the Elder, at the bridge.","s":[0]},{"h":"Beat the <b>Slime<\/b> group up the path with plain attacks; Sandy helps and cannot fall.","s":[0]},{"h":"Search behind the monument on the left for a <a href=\"#gear/shield-pot-lid\">Pot Lid<\/a>.","s":[0]},{"h":"Equip the <a href=\"#gear/shield-pot-lid\">Pot Lid<\/a> only if you kept the sword.","s":[0]},{"h":"Turn right at the first cave fork.","s":[0]},{"h":"Climb the wall.","s":[0]},{"h":"Take the <a href=\"#gear/item-medicinal-herb\">Medicinal Herb<\/a> by the tree.","s":[0]},{"h":"Start every fight by swinging at the monster on the field so it takes damage before the battle.","s":[0]},{"h":"Turn right at the fork past the bridge.","s":[0]},{"h":"Smash the pots by the stairs for a <a href=\"#gear/item-medicinal-herb\">Medicinal Herb<\/a> and 5G.","s":[0]},{"h":"Pick up the <a href=\"#gear/item-copper-ore\">Copper Ore<\/a> from the sparkly spot deeper in the caverns.","s":[0]},{"h":"Fight the pair of <a href=\"#boss/smog\">Smog<\/a>s.","s":[0]},{"h":"Keep HP above 10.","s":[0]},{"h":"Let Gemma heal you.","s":[0]},{"h":"Use <a href=\"#party/hero\">Frizz<\/a> if your hits keep missing.","s":[0]},{"h":"Grab the <a href=\"#gear/item-pink-pine\">Pink Pine<\/a> by the tree in the northwest corner.","s":[0]},{"h":"Climb the rope.","s":[0]},{"h":"After the Gryphon scene at the summit, take the second <a href=\"#gear/item-pink-pine\">Pink Pine<\/a> by the northwest tree.","s":[0]},{"h":"Enter the cave.","s":[0]}],"get_h":["<a href=\"#gear/shield-pot-lid\">Pot Lid<\/a> - chest behind the monument at the base"],"source":[{"t":"Birth of a Luminary / Prologue / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/prologue/birth-of-a-luminary"}]},"p-cobblestone":{"steps":[{"h":"Go to your house in the northeast.","s":[1]},{"h":"Talk to Amber to receive the <a href=\"#gear/item-precious-pendant\">Precious Pendant<\/a>.","s":[1]},{"h":"Leave the house at night.","s":[1]},{"h":"Meet Gemma by the large tree near the entrance.","s":[1]},{"h":"Search your home: the cupboard has <a href=\"#gear/armor-plain-clothes\">Plain Clothes<\/a> and the upstairs pots hold 10G.","s":[1]},{"h":"Climb the crates onto the shed roof next door for a 50G chest and a <a href=\"#gear/item-flurry-feather\">Flurry Feather<\/a>.","s":[1]},{"h":"Talk to the quest villager below your house to start <a href=\"#quests/the-people-s-friend\">The People&#x27;s Friend<\/a>.","s":[1]},{"h":"Hand over the <a href=\"#gear/item-flurry-feather\">Flurry Feather<\/a> for a <a href=\"#gear/item-sleeping-hibiscus\">Sleeping Hibiscus<\/a>.","s":[1]},{"h":"Check every bookshelf you pass from now on; red books can be recipe books.","s":[1]},{"h":"Buy a <a href=\"#gear/headwear-bandana\">Bandana<\/a> and <a href=\"#gear/armor-wayfarer-s-clothes\">Wayfarer&#x27;s Clothes<\/a> at the Item Shop.","s":[1]},{"h":"Skip the <a href=\"#gear/weapon-cypress-stick\">Cypress Stick<\/a>.","s":[1]},{"h":"Smash the barrels in the southeast cave for a <a href=\"#gear/item-seed-of-agility\">Seed of Agility<\/a>, a <a href=\"#gear/item-copper-ore\">Copper Ore<\/a> and 7G.","s":[1]},{"h":"Open the chest behind Gemma&#x27;s house for a <a href=\"#gear/weapon-cypress-stick\">Cypress Stick<\/a>.","s":[1]},{"h":"Climb Gemma&#x27;s roof for a <a href=\"#gear/item-medicinal-herb\">Medicinal Herb<\/a>.","s":[1]},{"h":"Take the <a href=\"#gear/item-fresh-water\">Fresh Water<\/a> at the top of the waterfall by your house.","s":[1]},{"h":"Go to the north entrance.","s":[1]},{"h":"Talk to Dunstan for the Map of Erdrea, a horse and Gemma&#x27;s Charm.","s":[1]}],"get_h":["<a href=\"#gear/item-seed-of-agility\">Seed of Agility<\/a> - barrel in the southeast cave","50G and <a href=\"#gear/item-flurry-feather\">Flurry Feather<\/a> - shed roof next to your house"],"source":[{"t":"Cobblestone / Prologue / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/prologue/cobblestone"}]},"a1-heliodor-region":{"steps":[{"h":"Equip Gemma&#x27;s Charm, which you just received.","s":[2]},{"h":"Travel on foot instead of by horse, so a strike on a field monster opens the battle with damage already dealt.","s":[2]},{"h":"Search the ruins on the left before the first clearing for a <a href=\"#gear/item-chimaera-wing\">Chimaera Wing<\/a>.","s":[2]},{"h":"Kill <b>Stark Raven<\/b>s first in each fight, since they speed themselves up.","s":[2]},{"h":"Keep right on the north path to open a chest with a <a href=\"#gear/item-seed-of-life\">Seed of Life<\/a>.","s":[2]},{"h":"Spend your first skill points on <a href=\"#party/hero\">Greatsword Guard<\/a> for greatswords or <b>Flame Slash<\/b> for swords.","s":[2]},{"h":"Save at the camp statue.","s":[2]},{"h":"Loot the cabin pots, the 80G chest behind it and the well&#x27;s <a href=\"#gear/item-strong-medicine\">Strong Medicine<\/a>.","s":[2]},{"h":"Go east from camp.","s":[2]},{"h":"Mine the crystal on the south wall for 2 <a href=\"#gear/item-copper-ore\">Copper Ore<\/a> and a <a href=\"#gear/item-flintstone\">Flintstone<\/a>.","s":[2]},{"h":"Level up on <b>Bunicorn<\/b>s and <b>Stark Raven<\/b>s along the Road to the Emerald Coast; the tent at its end has a <a href=\"#gear/item-chimaera-wing\">Chimaera Wing<\/a>.","s":[2]},{"h":"Keep HP above 15 on the eastern path, where <b>Hammerhood<\/b>s and <b>Fright Bulb<\/b>s appear.","s":[2]},{"h":"Open the chest behind the wall where the <b>Platypunk<\/b> slumps for a <a href=\"#gear/item-single-phial\">Single Phial<\/a>.","s":[2]},{"h":"Take the southwest path for the <a href=\"#gear/item-toad-oil\">Toad Oil<\/a> barrel on the pier and the <a href=\"#gear/item-fresh-water\">Fresh Water<\/a> spot.","s":[2]},{"h":"Rest at camp.","s":[2]},{"h":"Cross the north bridge.","s":[2]},{"h":"Harvest the northwest flower point.","s":[2]},{"h":"Enter Heliodor.","s":[2]}],"get_h":["<a href=\"#gear/item-seed-of-life\">Seed of Life<\/a> - chest on the north path, keep right","<a href=\"#gear/item-single-phial\">Single Phial<\/a> - chest behind the wall on the eastern path"],"source":[{"t":"Heliodor Region / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/heliodor-region"}]},"a1-heliodor":{"steps":[{"h":"Talk to the man by the castle stairs north of the fountain to start <a href=\"#quests/the-soldier-and-the-strategist-a-tale-of-two-heroes\">The Soldier and the Strategist - A Tale of Two Heroes<\/a>.","s":[3]},{"h":"Buy a new sword or greatsword at the Weapon shop, plus a <a href=\"#gear/headwear-leather-hat\">Leather Hat<\/a> and <a href=\"#gear/armor-leather-armor\">Leather Armour<\/a> (<a href=\"#gear/shield-leather-shield\">Leather Shield<\/a> for sword users).","s":[3]},{"h":"Climb the ladder south of the shops.","s":[3]},{"h":"Drop down the large house&#x27;s chimney.","s":[3]},{"h":"Open the balcony chest for a <a href=\"#gear/accessory-gold-bracer\">Gold Bracer<\/a>.","s":[3]},{"h":"Talk to the girl outside the Inn to start <a href=\"#quests/amelia-s-in-a-pickle\">Amelia&#x27;s in a Pickle!<\/a>.","s":[3]},{"h":"Climb the Item shop ladder to the roof.","s":[3]},{"h":"Pick up the cat.","s":[3]},{"h":"Jump the crate to the east roof for a mini medal.","s":[3]},{"h":"Return the cat to the girl to receive <a href=\"#gear/item-kitty-litter\">Kitty Litter<\/a>.","s":[3]},{"h":"Search the bookshelf in the far southeast house for the quest book.","s":[3]},{"h":"Give the book to the man by the castle stairs for a <a href=\"#gear/item-drasilian-shilling\">Drasilian Shilling<\/a>.","s":[3]},{"h":"Open the chest under the stairs of the northeast Royal Square house for 100G.","s":[3]},{"h":"Go through the bush in the southeast house&#x27;s garden to the hidden chest with a <a href=\"#gear/item-seed-of-sorcery\">Seed of Sorcery<\/a>.","s":[3]},{"h":"Enter the castle by day.","s":[3]},{"h":"Loot the castle first; the top-floor balcony barrel holds a mini medal.","s":[3]},{"h":"Go to the throne room to meet the King; this moves the story on.","s":[3]}],"get_h":["Mini medal - roof chest east of the Item shop","Mini medal - castle top-floor balcony barrel","<a href=\"#gear/accessory-gold-bracer\">Gold Bracer<\/a> - balcony chest of the large house west of the fountain","<a href=\"#gear/item-seed-of-deftness\">Seed of Deftness<\/a> - pot in the same house, entered by the chimney","<a href=\"#gear/item-seed-of-strength\">Seed of Strength<\/a> - barrel behind the guard east of town","<a href=\"#gear/item-seed-of-therapeusis\">Seed of Therapeusis<\/a> - castle top floor, east corridor pot"],"source":[{"t":"Heliodor / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/heliodor"}]},"a1-sewers":{"steps":[{"h":"Smash the pots in your cell.","s":[4]},{"h":"Walk to the cell door to meet the other prisoner.","s":[4]},{"h":"Go back into the cell.","s":[4]},{"h":"Talk to your partner to find the hidden passage.","s":[4]},{"h":"Turn right at the first junction for a <a href=\"#gear/item-medicinal-herb\">Medicinal Herb<\/a> by the locked door.","s":[4]},{"h":"Take the other path.","s":[4]},{"h":"Run from the soldiers at the bridge.","s":[4]},{"h":"If the soldiers catch you, heal during the fight before HP gets low.","s":[4]},{"h":"Run to the crates to sneak past the guards.","s":[4]},{"h":"Wait for the next guard to turn his back.","s":[4]},{"h":"Wait for the final guard to walk north.","s":[4]},{"h":"Save at the Goddess Statue in the caves below.","s":[4]},{"h":"Flee the <b>Black Dragon<\/b> without fighting by dashing toward the screen until you jump into the water.","s":[4]}],"get_h":[],"source":[{"t":"Heliodor Sewers / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/heliodor-sewers"}]},"a1-return-heliodor":{"steps":[{"h":"Smash the pots by your bed.","s":[5]},{"h":"Talk to the Priest.","s":[5]},{"h":"Talk to <a href=\"#party/erik\">Erik<\/a> outside to recruit him.","s":[5]},{"h":"Set Erik to manual control.","s":[5]},{"h":"Build Erik&#x27;s Knives toward <a href=\"#party/erik\">Sleeper Hit<\/a> and Pursecutter, plus <a href=\"#party/erik\">Half-Inch<\/a>.","s":[5]},{"h":"Talk to the warrior by the church to start <a href=\"#quests/it-takes-two-to-tango\">It Takes Two to Tango<\/a>.","s":[5]},{"h":"Finish a monster with The Real Decoy when both are pepped.","s":[5]},{"h":"Climb down the church well for a <a href=\"#gear/headwear-pointy-hat\">Pointy Hat<\/a> (equip it), a <a href=\"#gear/item-small-scale\">Small Scale<\/a> and a <a href=\"#gear/item-hardy-hide\">Hardy Hide<\/a>.","s":[5]},{"h":"Kill <b>Stump Chump<\/b>s first since they heal allies.","s":[5]},{"h":"Keep HP up against <b>Great Sabrecub<\/b>s.","s":[5]},{"h":"Open the hidden chest between a tree and rocks in the southeast of the open area for a <a href=\"#gear/item-red-eye\">Red Eye<\/a>.","s":[5]},{"h":"Follow the south path past the bridge to the chest with a <a href=\"#gear/item-seed-of-strength\">Seed of Strength<\/a>.","s":[5]},{"h":"Keep HP topped up across the bridge, where <a href=\"#boss/great-sabrecat\">Great Sabrecat<\/a>s have high HP and hard hits.","s":[5]},{"h":"Turn in the quest at the church for a <a href=\"#gear/accessory-gold-chain\">Gold Chain<\/a>.","s":[5]},{"h":"Equip the <a href=\"#gear/accessory-gold-chain\">Gold Chain<\/a>.","s":[5]},{"h":"Harvest <a href=\"#gear/item-buzzberries\">Buzzberries<\/a> at the tree point on the hill path before entering Downtown Heliodor.","s":[5]},{"h":"Buy Erik the better dagger and <a href=\"#gear/armor-leather-armor\">Leather Armour<\/a> in Downtown Heliodor.","s":[5]},{"h":"Give a <a href=\"#gear/item-holy-water\">Holy Water<\/a> and a <a href=\"#gear/item-buzzberries\">Buzzberries<\/a> to the girl with the dog.","s":[5]},{"h":"Let the dog scare off the guard instead of paying 2000G.","s":[5]},{"h":"Cross the roofs to Derk&#x27;s Shop in the Royal Square.","s":[5]},{"h":"Smash the upstairs pots for a mini medal.","s":[5]},{"h":"Leave through Downtown.","s":[5]},{"h":"Head southwest to The Manglegrove.","s":[5]}],"get_h":["Mini medal - upstairs pots in Derk&#x27;s Shop","<a href=\"#gear/headwear-pointy-hat\">Pointy Hat<\/a> - chest in the well outside the church","<a href=\"#gear/accessory-gold-chain\">Gold Chain<\/a> - reward for It Takes Two to Tango","<a href=\"#gear/item-drasilian-guinea\">Drasilian Guinea<\/a> - upper-layer drop-down chest in Downtown Heliodor; sells for 500G"],"source":[{"t":"Return to Heliodor / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/return-to-heliodor"}]},"a1-manglegrove":{"steps":[{"h":"Talk to the merchant south of the entrance; he sells <a href=\"#gear/item-flintstone\">Flintstone<\/a>, <a href=\"#gear/item-small-scale\">Small Scale<\/a> and <a href=\"#gear/item-fresh-water\">Fresh Water<\/a> for forging.","s":[6]},{"h":"Target <b>Dancing Devil<\/b>s and <b>Sham Hatwitch<\/b>es early, and carry <a href=\"#gear/item-antidotal-herb\">Antidotal Herb<\/a>s for <b>Bubble Slime<\/b> poison.","s":[6]},{"h":"Talk to every cow you find; they forecast weather and 10 of them unlock a trophy.","s":[6]},{"h":"Take the east path.","s":[6]},{"h":"Climb the ledges to the flower point.","s":[6]},{"h":"Open the ledge chest for a mini medal.","s":[6]},{"h":"Cross the south bridge to the camp, where Erik hands over the <a href=\"#gear/item-fun-size-forge\">Fun-Size Forge<\/a> and a recipe book.","s":[6]},{"h":"Forge the <a href=\"#gear/weapon-divine-dagger\">Divine Dagger<\/a> for Erik from a <a href=\"#gear/item-copper-ore\">Copper Ore<\/a> and <a href=\"#gear/item-fresh-water\">Fresh Water<\/a> if the Luminary uses greatswords.","s":[6]},{"h":"Spend the pearls you earn reworking the Luminary&#x27;s greatsword.","s":[6]},{"h":"Open the chest in the camp hut for <a href=\"#forge/book-economies-of-scale\">Economies of Scale<\/a>.","s":[6]},{"h":"Forge <a href=\"#gear/armor-scale-armor\">Scale Armour<\/a> (and a <a href=\"#gear/shield-scale-shield\">Scale Shield<\/a> for sword users).","s":[6]},{"h":"Touch the root east of camp.","s":[6]},{"h":"Take the west path from the central clearing to the hidden chest.","s":[6]},{"h":"Fight the <a href=\"#boss/tricky-devil\">Tricky Devil<\/a> (145 HP) with regular attacks.","s":[6]},{"h":"Keep everyone above 20 HP because of its <a href=\"#party/hero\">Sizz<\/a>.","s":[6]},{"h":"Cross the repaired bridge.","s":[6]},{"h":"Climb the rope at the far end.","s":[6]},{"h":"Open the chest north of the ore point for a <a href=\"#gear/item-single-phial\">Single Phial<\/a>.","s":[6]},{"h":"Exit east.","s":[6]},{"h":"Detour into the cave east of the Cobblestone entrance for 5 pearls.","s":[6]},{"h":"Go south to Cobblestone.","s":[6]}],"get_h":["<a href=\"#gear/item-fun-size-forge\">Fun-Size Forge<\/a> - from Erik at the camp","<a href=\"#forge/book-economies-of-scale\">Economies of Scale<\/a> - chest in the camp hut","Mini medal - ledge chest on the east path"],"source":[{"t":"The Manglegrove / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/the-manglegrove"}]},"a1-emerald-coast":{"steps":[{"h":"Go to your house.","s":[7]},{"h":"Talk to Amber.","s":[7]},{"h":"Follow young Gemma to the pier.","s":[7]},{"h":"Talk to the boy and old man.","s":[7]},{"h":"Return up to the village to end the vision of the past.","s":[7]},{"h":"Open the chest in the ruined church for <a href=\"#forge/book-o-holy-knight\">O Holy Knight<\/a>.","s":[7]},{"h":"Leave by the north exit.","s":[7]},{"h":"Take the east path to The Emerald Coast.","s":[7]},{"h":"Examine the three-sided rock at Cobblestone Falls to dig up the box with the letters and the Keystone.","s":[7]},{"h":"Open the chest on the cliff west of the weather cow for a <a href=\"#gear/item-hardy-hide\">Hardy Hide<\/a>.","s":[7]},{"h":"Rest at the camp.","s":[7]},{"h":"Forge a <a href=\"#gear/armor-templar-s-uniform\">Templar&#x27;s Uniform<\/a> for Erik from <a href=\"#gear/item-buzzberries\">Buzzberries<\/a> and <a href=\"#gear/item-cottontop\">Cottontop<\/a>, reworking it toward +3.","s":[7]},{"h":"Skip the new greatsword in the camp shop if you already have a <a href=\"#gear/weapon-copper-chopper\">Copper Chopper<\/a> +3.","s":[7]},{"h":"Harvest the tree point northeast of camp and the flower point toward the beach.","s":[7]},{"h":"Rest at camp again.","s":[7]},{"h":"Leave the area to the south for The Kingsbarrow.","s":[7]}],"get_h":["<a href=\"#forge/book-o-holy-knight\">O Holy Knight<\/a> - chest in the ruined Cobblestone church"],"source":[{"t":"Cobblestone and The Emerald Coast / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/cobblestone-and-the-emerald-coast"}]},"a1-kingsbarrow":{"steps":[{"h":"Smash the pot in the tent at the start for a <a href=\"#gear/item-single-phial\">Single Phial<\/a>.","s":[8]},{"h":"Go downstairs.","s":[8]},{"h":"Turn right at the first junction.","s":[8]},{"h":"Climb outside for the <a href=\"#gear/item-hardy-hide\">Hardy Hide<\/a> spot by the rubble.","s":[8]},{"h":"Climb out at the next junction.","s":[8]},{"h":"Go south to the chest with a <a href=\"#gear/accessory-strength-ring\">Strength Ring<\/a>.","s":[8]},{"h":"Give the <a href=\"#gear/accessory-strength-ring\">Strength Ring<\/a> to the Luminary.","s":[8]},{"h":"Defeat the <b>Mecha-mynah<\/b>s in the north room.","s":[8]},{"h":"Take the <a href=\"#gear/item-wing-of-bat\">Wing of Bat<\/a> spot.","s":[8]},{"h":"Open the chest behind the <a href=\"#boss/smog\">Smog<\/a> group to the west for a <a href=\"#gear/armor-templar-s-uniform\">Templar&#x27;s Uniform<\/a>.","s":[8]},{"h":"Defeat a sparkling <b>Eggsoskeleton<\/b>.","s":[8]},{"h":"Mount the <b>Eggsoskeleton<\/b>.","s":[8]},{"h":"Jump to the chests with a <a href=\"#gear/item-seed-of-defence\">Seed of Defence<\/a> and <a href=\"#forge/book-put-a-feather-in-your-cap\">Put a Feather in Your Cap<\/a>.","s":[8]},{"h":"Drop to the door for 2 <a href=\"#gear/item-magic-water\">Magic Water<\/a>.","s":[8]},{"h":"Heal everyone to full HP and MP.","s":[8]},{"h":"Fight the <a href=\"#boss/grim-gryphon\">Grim Gryphon<\/a>s (about 130HP each).","s":[8]},{"h":"Sleep them with <b>Sleeper Hit<\/b>.","s":[8]},{"h":"Hit them with <a href=\"#party/hero\">Sizz<\/a>.","s":[8]},{"h":"Use <b>Scorched Earth<\/b> instead if both of you are pepped.","s":[8]},{"h":"Use <a href=\"#party/hero\">Evac<\/a> to leave.","s":[8]},{"h":"Rest at the Emerald Coast camp.","s":[8]},{"h":"Try the forge&#x27;s first flourish (a forge technique that strikes two gauges at once); it unlocks if you are at least level 10.","s":[8]},{"h":"Forge a <a href=\"#gear/headwear-feathered-cap\">Feathered Cap<\/a> each for the Luminary and Erik from a <a href=\"#gear/item-hardy-hide\">Hardy Hide<\/a> and a <a href=\"#gear/item-flurry-feather\">Flurry Feather<\/a>.","s":[8]},{"h":"Walk east under the tree to the Door of Departure.","s":[8]}],"get_h":["<a href=\"#forge/book-put-a-feather-in-your-cap\">Put a Feather in Your Cap<\/a> - Basement 3F chest, reached on an Eggsoskeleton mount","<a href=\"#gear/accessory-strength-ring\">Strength Ring<\/a> - chest outside the temple&#x27;s upper level","<a href=\"#gear/item-seed-of-defence\">Seed of Defence<\/a> - Basement 3F chest"],"source":[{"t":"The Kingsbarrow / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/the-kingsbarrow"}]},"a1-hotto":{"steps":[{"h":"Save with the Priest by the Door.","s":[9]},{"h":"Kill <b>Bongo Drongo<\/b>s first since they call help as well as raising enemy attack.","s":[9]},{"h":"Grab the <a href=\"#gear/item-warmaline\">Warmaline<\/a> and <a href=\"#gear/item-lava-lump\">Lava Lump<\/a> spots south of town.","s":[9]},{"h":"Enter Hotto.","s":[9]},{"h":"Open the chest behind the west house for a mini medal and the chest behind the Inn for <a href=\"#forge/book-an-introduction-to-armor\">An Introduction to Armour<\/a>.","s":[9]},{"h":"Talk to the blacksmith west of the second Item shop to start <a href=\"#quests/smiths-and-sparkly-spots\">Smiths and Sparkly Spots<\/a>.","s":[9]},{"h":"Talk to the man behind the bar to start <a href=\"#quests/put-a-ring-on-it\">Put a Ring on It<\/a> and receive <a href=\"#forge/book-twenty-four-carats-of-class\">Twenty-Four Carats of Class<\/a> and 2 <a href=\"#gear/item-gold-ore\">Gold Ore<\/a>.","s":[9]},{"h":"Buy Erik a <a href=\"#gear/weapon-poison-moth-knife\">Poison Moth Knife<\/a>, but hold off on the iron weapons and <a href=\"#gear/armor-chain-mail\">Chain Mail<\/a>.","s":[9]},{"h":"Pay the woman at the end of the bath walkway 20G for a puff-puff; it counts toward a trophy.","s":[9]},{"h":"Bring Connie to the girl at the entrance so <a href=\"#party/veronica\">Veronica<\/a> joins you.","s":[9]},{"h":"Go to the bar.","s":[9]},{"h":"Mine <a href=\"#gear/item-iron-ore\">Iron Ore<\/a> west across the bridge.","s":[9]},{"h":"Forge <a href=\"#gear/armor-bronze-armor\">Bronze Armour<\/a> and the <a href=\"#gear/accessory-gold-ring\">Gold Ring<\/a> +1 at the camp.","s":[9]},{"h":"Fly back to Hotto.","s":[9]},{"h":"Turn in both quests for <a href=\"#forge/book-i-iron-arms\">I ♥ Iron Arms<\/a> and a <a href=\"#gear/weapon-crucerang\">Crucerang<\/a>.","s":[9]},{"h":"Forge a <a href=\"#gear/weapon-cast-iron-claymore\">Cast-Iron Claymore<\/a> for the Luminary from <a href=\"#gear/item-iron-ore\">Iron Ore<\/a> and <a href=\"#gear/item-copper-ore\">Copper Ore<\/a>, aiming for +3.","s":[9]},{"h":"Go south from camp.","s":[9]},{"h":"Hug the cliff east of the <a href=\"#gear/item-glass-frit\">Glass Frit<\/a> spot.","s":[9]},{"h":"Open the chest for a mini medal.","s":[9]},{"h":"Go northwest from camp past the ore point.","s":[9]},{"h":"Enter The Cryptic Crypt.","s":[9]}],"get_h":["Mini medal - chest behind the west house in Hotto","Mini medal - chest in the far southwest of the Steppe","<a href=\"#forge/book-an-introduction-to-armor\">An Introduction to Armour<\/a> - chest behind the Hotto Inn","<a href=\"#forge/book-twenty-four-carats-of-class\">Twenty-Four Carats of Class<\/a> - from the Put a Ring on It quest giver","<a href=\"#forge/book-i-iron-arms\">I ♥ Iron Arms<\/a> - reward for Smiths and Sparkly Spots","<a href=\"#gear/weapon-crucerang\">Crucerang<\/a> - reward for Put a Ring on It"],"source":[{"t":"Hotto and The Hotto Steppe / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/hotto-and-the-hotto-steppe"}]},"a1-cryptic-crypt":{"steps":[{"h":"Make <b>Mud Mannequin<\/b>s and <b>Skullrider<\/b>s your first targets in every fight.","s":[10]},{"h":"Walk toward the chest at the second junction to fall through.","s":[10]},{"h":"Open the chest behind you for a <a href=\"#gear/item-yggdrasil-leaf\">Yggdrasil Leaf<\/a>.","s":[10]},{"h":"Take the west path near the root to drop again for a <a href=\"#gear/headwear-feathered-cap\">Feathered Cap<\/a> and 2 <a href=\"#gear/item-gold-ore\">Gold Ore<\/a>.","s":[10]},{"h":"Defeat the sparkling <b>Skullrider<\/b>.","s":[10]},{"h":"Ride the <b>Skullrider<\/b> up the walls marked with footprints.","s":[10]},{"h":"Climb back up.","s":[10]},{"h":"Collect the chests on that floor: 1000G, <a href=\"#gear/accessory-robber-gloves\">Robber Gloves<\/a>, a mini medal and a <a href=\"#gear/shield-silver-platter\">Silver Platter<\/a>.","s":[10]},{"h":"Save at the Goddess Statue by the fountain.","s":[10]},{"h":"Give Erik some <a href=\"#gear/item-medicinal-herb\">Medicinal Herb<\/a>s.","s":[10]},{"h":"Touch the root to learn the password.","s":[10]},{"h":"Say it at the door.","s":[10]},{"h":"Fight <a href=\"#boss/jarvis\">Jarvis<\/a> (around 260 HP) and his Shadows (around 70 HP).","s":[10]},{"h":"Open with <b>Cutting Edge<\/b>.","s":[10]},{"h":"Follow with Erik&#x27;s <a href=\"#party/erik\">Sleeper Hit<\/a> into Pursecutter.","s":[10]},{"h":"Heal the party right after Jarvis uses Cool Breath.","s":[10]},{"h":"Do not bother stealing.","s":[10]},{"h":"Take the <a href=\"#gear/item-iron-ore\">Iron Ore<\/a> spot and the <a href=\"#gear/item-grubby-bandage\">Grubby Bandage<\/a> pot in the boss room.","s":[10]},{"h":"Build <a href=\"#party/veronica\">Veronica<\/a> in Heavy Wands and Vim, and <a href=\"#party/serena\">Serena<\/a> in Wands and Harpistry.","s":[10]},{"h":"Give Serena the <a href=\"#gear/shield-silver-platter\">Silver Platter<\/a> if the Luminary uses greatswords.","s":[10]},{"h":"Leave Hotto to learn <a href=\"#party/hero\">Zoom<\/a>.","s":[10]},{"h":"Sell your <a href=\"#gear/item-chimaera-wing\">Chimaera Wing<\/a>s.","s":[10]},{"h":"Go southwest to the checkpoint.","s":[10]},{"h":"Show your pass at the checkpoint to enter the Gallopolis Region.","s":[10]}],"get_h":["Mini medal - Basement 1F chest","<a href=\"#gear/accessory-robber-gloves\">Robber Gloves<\/a> - Basement 1F chest","<a href=\"#gear/item-yggdrasil-leaf\">Yggdrasil Leaf<\/a> - chest in the pit","1000G - Basement 1F chest"],"source":[{"t":"The Cryptic Crypt / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/the-cryptic-crypt"}]},"a1-gallopolis":{"steps":[{"h":"Open the chest on the western edge south of Gallopolis for a mini medal.","s":[11]},{"h":"Register the southwest camp.","s":[11]},{"h":"In town, open the southwest-corner chest for a mini medal.","s":[11]},{"h":"Take <a href=\"#forge/book-so-you-want-to-be-a-witch\">So You Want to Be a Witch<\/a> from the Inn bookshelf.","s":[11]},{"h":"Accept <a href=\"#quests/a-walk-on-the-wild-side\">A Walk on the Wild Side<\/a> from the painter in the northwest and <a href=\"#quests/a-cactus-cutlet-to-die-for\">A Cactus Cutlet to Die For<\/a> in the Tavern.","s":[11]},{"h":"Buy <a href=\"#gear/headwear-bunny-ears\">Bunny Ears<\/a> for the girls, but skip the shop wands since you can forge better.","s":[11]},{"h":"Loot the palace, including 1500G behind the throne.","s":[11]},{"h":"Meet Faris at the circus at night.","s":[11]},{"h":"Win the Sand National by grabbing every green swirl and letting go of dash when stamina runs low.","s":[11]},{"h":"Fight <b>Cactiball<\/b>s near the South Campsite until a <b>Golden Globe<\/b> joins a battle.","s":[11]},{"h":"Turn in the globule.","s":[11]},{"h":"Forge the <a href=\"#gear/weapon-wizard-s-staff\">Wizard&#x27;s Staff<\/a> for Veronica first.","s":[11]},{"h":"Forge the <a href=\"#gear/headwear-tricky-turban\">Tricky Turban<\/a> and <a href=\"#gear/accessory-enchantress-s-gloves\">Enchantress&#x27;s Gloves<\/a> next.","s":[11]},{"h":"At night in the Celestial Sands, with the Luminary, Erik and Serena pepped, finish a <b>Spitzfire<\/b> with <b>Wild Side<\/b>.","s":[11]},{"h":"Fight the <a href=\"#boss/slayer-of-the-sands\">Slayer of the Sands<\/a> (around 710 HP).","s":[11]},{"h":"Cast <b>Sap<\/b> and <b>Decelerate<\/b> on it.","s":[11]},{"h":"Keep <b>Buff<\/b> on Veronica.","s":[11]},{"h":"Answer <b>Kasap<\/b> with Buff.","s":[11]},{"h":"Hit it with <a href=\"#party/hero\">Zap<\/a> or <b>Cutting Edge<\/b>, Veronica&#x27;s <b>Frizz<\/b>, and Erik&#x27;s <a href=\"#party/erik\">Sleeper Hit<\/a> into Pursecutter.","s":[11]},{"h":"Switch the Luminary to healing if Serena is confused.","s":[11]},{"h":"Win the Bronze and Silver Cups at the track, cutting right at turn 3 on the Silver course.","s":[11]},{"h":"Put <a href=\"#party/sylvando\">Sylvando<\/a> on the path to <a href=\"#party/sylvando\">Hustle Dance<\/a> right away.","s":[11,12]},{"h":"Accept <a href=\"#quests/a-lovely-letter\">A Lovely Letter<\/a> at the western checkpoint.","s":[11]},{"h":"Show the Sultan&#x27;s letter to enter Gondolia.","s":[11]}],"get_h":["Mini medal - chest south of Gallopolis","Mini medal - southwest-corner chest in town","<a href=\"#forge/book-so-you-want-to-be-a-witch\">So You Want to Be a Witch<\/a> - Inn bookshelf","<a href=\"#gear/accessory-traveller-s-hood\">Traveller&#x27;s Hood<\/a> - church wardrobe","<a href=\"#gear/accessory-gold-bracer\">Gold Bracer<\/a> - Bronze Cup on the difficult setting","<a href=\"#gear/armor-gallopolitan-garb\">Gallopolitan Garb<\/a> - Silver Cup on easy"],"source":[{"t":"The Sultanate of Gallopolis / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/the-sultanate-of-gallopolis"}]},"a1-gondolia":{"steps":[{"h":"Defeat a sparkling <b>Midnight Horknight<\/b>.","s":[13]},{"h":"Fly the <b>Midnight Horknight<\/b> to the small islands, including the <a href=\"#gear/item-seed-of-skill\">Seed of Skill<\/a> chest for Sylvando.","s":[13]},{"h":"Kill <b>Muddy Hand<\/b>s first because they keep calling for help.","s":[13]},{"h":"Open the central-platform chest for a mini medal and the northern island chest for <a href=\"#forge/book-i-iron-armor\">I ♥ Iron Armour<\/a>.","s":[13]},{"h":"Take <a href=\"#forge/book-a-slender-sword-of-solid-silver\">A Slender Sword of Solid Silver<\/a> from the western swamp&#x27;s central platform.","s":[13]},{"h":"Forge Sylvando a <a href=\"#gear/weapon-silver-rapier\">Silver Rapier<\/a> at the camp after reporting your targets.","s":[13]},{"h":"Take <a href=\"#forge/book-filigree-for-fun-and-profit\">Filigree for Fun and Profit<\/a> from the Gondolia church bookshelf.","s":[13]},{"h":"Haggle between the two Cat Suit brothers until it drops to 1,000G if you want Veronica&#x27;s cat look.","s":[13]},{"h":"Swap letters with the woman near the Doge&#x27;s house and the Gallopolis guard for <a href=\"#forge/book-cutting-edge-kit\">Cutting-Edge Kit<\/a>.","s":[13]},{"h":"Accept <a href=\"#quests/an-even-lovelier-letter\">An Even Lovelier Letter<\/a>.","s":[13]},{"h":"Search the upstairs wardrobe in the house north of her for a mini medal.","s":[13]},{"h":"At the Grotta della Fonte camp, forge <a href=\"#gear/shield-gold-platter\">Gold Platter<\/a>s, a <a href=\"#gear/headwear-fur-hood\">Fur Hood<\/a>, an <a href=\"#gear/headwear-iron-mask\">Iron Mask<\/a> and <a href=\"#gear/armor-iron-cuirass\">Iron Cuirass<\/a>es.","s":[13]},{"h":"Fight the two <a href=\"#boss/coralossus\">Coralossus<\/a> (around 230 HP each) with the Luminary&#x27;s <a href=\"#party/hero\">Zap<\/a>, <b>Sap<\/b>, and <b>Oomph<\/b> on the Luminary and Erik.","s":[13]},{"h":"Climb the rope past the lake for the <a href=\"#gear/item-seed-of-magic\">Seed of Magic<\/a> and <a href=\"#gear/item-green-eye\">Green Eye<\/a> chests.","s":[13]},{"h":"Zoom to Gondolia.","s":[13]},{"h":"Beat the <a href=\"#boss/heliodorian-guard\">Heliodorian guard<\/a>s with <a href=\"#party/hero\">Zap<\/a> and <a href=\"#party/hero\">Bang<\/a>.","s":[13]},{"h":"Cross the Inn roofs.","s":[13]},{"h":"Take the gondola to the stage.","s":[13]},{"h":"Fight <a href=\"#boss/jasper\">Jasper<\/a> (around 630 HP).","s":[13]},{"h":"Use magic during Sword Stance.","s":[13]},{"h":"Keep <b>Buff<\/b> on Veronica.","s":[13]},{"h":"Cast <b>Sap<\/b> and <b>Decelerate<\/b> on him.","s":[13]},{"h":"Cure Fizzle fast.","s":[13]}],"get_h":["Mini medal - central swamp, central platform chest","Mini medal - wardrobe in the house north of the Doge&#x27;s","Mini medal - Grotta della Fonte, chest south of the camp","<a href=\"#forge/book-i-iron-armor\">I ♥ Iron Armour<\/a> - central swamp, northern island chest","<a href=\"#forge/book-a-slender-sword-of-solid-silver\">A Slender Sword of Solid Silver<\/a> - western swamp, central platform chest","<a href=\"#forge/book-filigree-for-fun-and-profit\">Filigree for Fun and Profit<\/a> - Gondolia church bookshelf"],"source":[{"t":"Gondolia / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/gondolia"}]},"a1-rainbough":{"steps":[{"h":"Stop at Insula Australis.","s":[14]},{"h":"Open the chest on the southern islet for <a href=\"#forge/book-rings-around-the-world\">Rings Around the World<\/a>.","s":[14]},{"h":"Kill <b>Tap Devil<\/b>s first in Zwaardsrust; they make the whole party dance and curse it.","s":[14]},{"h":"Search the hay field west of the Warrior&#x27;s Rest Inn slowly at night for a non-sparkling mini medal.","s":[14]},{"h":"Take <a href=\"#forge/book-smithing-with-steel\">Smithing with Steel<\/a> from the Inn&#x27;s upstairs bookshelf and the balcony chest&#x27;s mini medal.","s":[14]},{"h":"Accept <a href=\"#quests/a-path-to-paradise\">A Path to Paradise<\/a>.","s":[14]},{"h":"Use <b>Care Prayer<\/b> on a <b>Deadnaut<\/b> in the western ruins at night.","s":[14]},{"h":"Ride a <b>Horknight<\/b> over the lake in north Dundrasil to the chest with a <a href=\"#gear/accessory-necklace-of-immunity\">Necklace of Immunity<\/a>.","s":[14]},{"h":"In Octagonia, buy <a href=\"#gear/accessory-tough-guy-tattoo\">Tough Guy Tattoo<\/a>s for the Luminary and Erik and the <a href=\"#gear/weapon-rod-of-rapidity\">Rod of Rapidity<\/a> for Veronica.","s":[14]},{"h":"Take the mini medal pot in the alcove at the bottom of town and <a href=\"#forge/book-building-butterfly-bric-a-brac\">Building Butterfly Bric-a-Brac<\/a> in the Orphanage.","s":[14]},{"h":"In the tournament, use <b>Cutting Edge<\/b>.","s":[14]},{"h":"Focus <a href=\"#boss/underdigger\">Underdigger<\/a> first and <a href=\"#boss/sinderella\">Sinderella<\/a> second.","s":[14]},{"h":"Defend when both foes are pepped.","s":[14]},{"h":"Focus <a href=\"#boss/sterling-sylva\">Sterling Sylva<\/a>.","s":[14]},{"h":"Cure poison at once.","s":[14]},{"h":"Hit <a href=\"#party/rab\">Rab<\/a> first in the final.","s":[14]},{"h":"Heal below 80 HP.","s":[14]},{"h":"Trigger fights at the metal orbs in the Caverns under Octagonia for <b>Metal Slime<\/b>s.","s":[14]},{"h":"Take the <a href=\"#gear/weapon-assassin-s-dagger\">Assassin&#x27;s Dagger<\/a> for Erik.","s":[14]},{"h":"Beat the <b>Cannibox<\/b> in the right chest of the northwest pair for a <a href=\"#gear/item-seed-of-skill\">Seed of Skill<\/a>.","s":[14]},{"h":"Fight <a href=\"#boss/arachtagon\">Arachtagon<\/a> (around 1270 HP).","s":[14]},{"h":"Heal with <a href=\"#party/sylvando\">Hustle Dance<\/a>.","s":[14]},{"h":"Keep <b>Acceleratle<\/b> up.","s":[14]},{"h":"Cast <b>Buff<\/b> and <b>Sap<\/b>.","s":[14]},{"h":"Cast <b>Oomph<\/b> on Veronica for fire spells.","s":[14]},{"h":"Accept <a href=\"#quests/skincare-for-the-fierce-and-fabulous\">Skincare for the Fierce and Fabulous<\/a>.","s":[14]},{"h":"Finish <a href=\"#quests/the-shadow\">The Shadow<\/a> for a mini medal.","s":[14]}],"get_h":["Mini medal - hidden in the hay field west of Warrior&#x27;s Rest Inn","Mini medal - Warrior&#x27;s Rest Inn balcony chest","Mini medal - Octagonia, pot in the alcove under the stairs","Mini medal - Caverns under Octagonia, east chest","<a href=\"#forge/book-smithing-with-steel\">Smithing with Steel<\/a> - Warrior&#x27;s Rest Inn bookshelf","<a href=\"#forge/book-rings-around-the-world\">Rings Around the World<\/a> - Insula Australis, southern chest"],"source":[{"t":"Search for the Rainbough / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/search-for-the-rainbough"}]},"a1-dundrasil":{"steps":[{"h":"Build the Luminary toward <a href=\"#party/hero\">Cutting Edge<\/a>, <a href=\"#party/hero\">Frost Fangs<\/a> and <a href=\"#party/hero\">Zap<\/a>, Erik toward dual wielding, and Sylvando to <a href=\"#party/sylvando\">Hustle Dance<\/a>.","s":[15]},{"h":"Pick the gold flower point in the northwest for the <a href=\"#gear/item-mellow-vera\">Mellow Vera<\/a>.","s":[15]},{"h":"Shoot the target in the tree beside the flower point.","s":[15]},{"h":"Ride a <b>Horknight<\/b> to the west island for a <a href=\"#gear/item-drasilian-sovereign\">Drasilian Sovereign<\/a>.","s":[15]},{"h":"Climb the ruins northeast of the camp to the ladder and chest with a <a href=\"#gear/weapon-bandit-blade\">Bandit Blade<\/a>.","s":[15]},{"h":"Zoom to Octagonia to turn in <a href=\"#quests/skincare-for-the-fierce-and-fabulous\">Skincare for the Fierce and Fabulous<\/a> for a recipe book.","s":[15]},{"h":"Forge a <a href=\"#gear/weapon-batterfly-knife\">Batterfly Knife<\/a> if Erik dual wields, plus the <a href=\"#gear/armor-dapper-doublet\">Dapper Doublet<\/a> and <a href=\"#gear/accessory-natty-cravat\">Natty Cravat<\/a> for Sylvando.","s":[15]},{"h":"Climb the northern of the two small ruins to the balcony chest with a <a href=\"#gear/item-seed-of-life\">Seed of Life<\/a>.","s":[15]},{"h":"Open the chest on the north side of the shack by the Goddess Statue for a mini medal.","s":[15]},{"h":"Fight <b>Green Dragon<\/b>s in the castle ruins for 656 Exp each, but heal after their party-wide Flame Breath.","s":[15]},{"h":"Climb the ladder by the northeast bridge.","s":[15]},{"h":"Smash the pots there for a mini medal.","s":[15]},{"h":"Beat the <b>Cannibox<\/b> in the left chest of the northwest building.","s":[15]},{"h":"Take the <a href=\"#gear/accessory-dragon-scale\">Dragon Scale<\/a> from the right chest.","s":[15]},{"h":"Equip the <a href=\"#gear/accessory-dragon-scale\">Dragon Scale<\/a> on the Luminary or Erik.","s":[15]},{"h":"Climb into the well by the friendly Slime to enter the castle.","s":[15]},{"h":"Duck under the fallen pillar south of the gravestone for <a href=\"#forge/book-dress-like-a-drasilian\">Dress Like a Drasilian<\/a>.","s":[15]},{"h":"Take the <a href=\"#gear/accessory-devil-s-tail\">Devil&#x27;s Tail<\/a> from the north building.","s":[15]},{"h":"Build <a href=\"#party/jade\">Jade<\/a> in Spears toward <a href=\"#party/jade\">Multithrust<\/a> and <a href=\"#party/rab\">Rab<\/a> in Heavy Wands once they join.","s":[15]}],"get_h":["Mini medal - chest at the shack southwest of the castle ruins","Mini medal - pots up the ladder in the northeast castle ruins","<a href=\"#gear/accessory-dragon-scale\">Dragon Scale<\/a> - right-hand chest in the northwest ruined building","<a href=\"#forge/book-dress-like-a-drasilian\">Dress Like a Drasilian<\/a> - under the fallen pillar south of the gravestone","<a href=\"#gear/item-drasilian-sovereign\">Drasilian Sovereign<\/a> - northwestern island chest"],"source":[{"t":"To Dundrasil Castle Ruins / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/to-dundrasil-castle-ruins"}]},"a1-puerto-valor":{"steps":[{"h":"Sail northwest from the Gondolia dock to the Costa Valor dock.","s":[16]},{"h":"Grab the <a href=\"#gear/armor-tortoise-shell\">Tortoise Shell<\/a> chest on the hidden south beach and the <a href=\"#gear/headwear-coral-hairpin\">Coral Hairpin<\/a> chest on the offshore islet.","s":[16]},{"h":"Climb into the well by the camp for a <a href=\"#gear/item-pitch-pearl\">Pitch Pearl<\/a> chest.","s":[16]},{"h":"In Puerto Valor, climb the spiral stairs beside the Casino for a 1300G chest.","s":[16]},{"h":"Accept <a href=\"#quests/anything-for-love\">Anything for Love<\/a> in town.","s":[16]},{"h":"Accept <a href=\"#quests/shiver-me-timbers\">Shiver me Timbers!<\/a> in town.","s":[16]},{"h":"Accept <a href=\"#quests/a-rush-of-blood\">A Rush of Blood<\/a> in town.","s":[16]},{"h":"Trade your first 20 mini medals in the Hotel for a <a href=\"#gear/accessory-shield-bearer\">Shield-Bearer<\/a>, <a href=\"#gear/headwear-hermes-hat\">Hermes&#x27; Hat<\/a> and <a href=\"#gear/weapon-rune-staff\">Rune Staff<\/a>.","s":[16]},{"h":"Deliver the letter to Valentino in the beach restaurant.","s":[16]},{"h":"Report in Gondolia for a mini medal.","s":[16]},{"h":"Take <a href=\"#forge/book-your-crafting-career-starts-here\">Your Crafting Career Starts Here<\/a> from the house west of the restaurant.","s":[16]},{"h":"Get <a href=\"#forge/book-all-things-nice\">All Things Nice<\/a> from the man in red.","s":[16]},{"h":"Fight <a href=\"#boss/robbin-ood\">Robbin&#x27; &#x27;Ood<\/a> on Insula Australis.","s":[16]},{"h":"Drop his <a href=\"#boss/merry-man\">Merry Man<\/a> crew with <a href=\"#party/hero\">Zap<\/a> and <a href=\"#party/hero\">Sizzle<\/a>.","s":[16]},{"h":"Cure sealed spells.","s":[16]},{"h":"Defeat a <a href=\"#boss/coralossus\">Coralossus<\/a> on the Costa Valor beach for the Floral Coral.","s":[16]},{"h":"Turn in both quests.","s":[16]},{"h":"Buy <a href=\"#forge/book-down-the-rabbithole\">Down the Rabbithole<\/a> with casino tokens.","s":[16]},{"h":"Play poker for double or nothing.","s":[16]},{"h":"Step out of the casino and back in to autosave your winnings.","s":[16]},{"h":"Forge the <a href=\"#gear/armor-bunny-suit\">Bunny Suit<\/a>.","s":[16]},{"h":"Dress Jade in the <a href=\"#gear/armor-bunny-suit\">Bunny Suit<\/a>, the <a href=\"#gear/headwear-bunny-ears\">Bunny Ears<\/a> and <a href=\"#gear/accessory-fishnet-stockings\">Fishnet Stockings<\/a> to finish the old man&#x27;s quest.","s":[16]},{"h":"Talk to Servantes in Don Rodrigo&#x27;s mansion so he opens the sluice.","s":[16]},{"h":"Sail to the Valor-Sauvage Channel west of town.","s":[16]},{"h":"Follow the stream into the fog.","s":[16]}],"get_h":["Mini medal - Hotel bedroom pot","Mini medal - reward for An Even Lovelier Letter","<a href=\"#forge/book-your-crafting-career-starts-here\">Your Crafting Career Starts Here<\/a> - bookshelf in the house west of the restaurant","<a href=\"#forge/book-all-things-nice\">All Things Nice<\/a> - man in red at the entrance","<a href=\"#forge/book-down-the-rabbithole\">Down the Rabbithole<\/a> - casino prize","<a href=\"#gear/headwear-coral-hairpin\">Coral Hairpin<\/a> - Costa Valor northeast beach chest"],"source":[{"t":"To Puerto Valor / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/to-puerto-valor"}]},"a1-green-orb":{"steps":[{"h":"Open the chest behind the western ship on The Strand for a mini medal.","s":[17]},{"h":"Talk to Jade and Michelle.","s":[17]},{"h":"Climb the steps left of the arch on Insula Incognita for <a href=\"#forge/book-crafting-comforting-clothing\">Crafting Comforting Clothing<\/a>.","s":[17]},{"h":"Beware the hard-hitting <b>Cyclops<\/b> there.","s":[17]},{"h":"Smash the pots behind the cabin on Insula Occidentalis for a mini medal.","s":[17]},{"h":"Grab the <a href=\"#gear/item-slime-crown\">Slime Crown<\/a> chest and the ruins mini medal on Insula Orientalis.","s":[17]},{"h":"Hunt <b>Liquid Metal Slime<\/b>s that appear with <b>King Slime<\/b>s.","s":[17]},{"h":"In Lonalulu, read the Armor shop shelf for <a href=\"#forge/book-my-first-pearly-pieces\">My First Pearly Pieces<\/a>.","s":[17]},{"h":"Open the chest behind the Weapons counter.","s":[17]},{"h":"Search behind the beach stairs for 3000G and the barrels south of the Tavern for a mini medal.","s":[17]},{"h":"Talk to the Canon Lady for a cannon.","s":[17]},{"h":"Sail to the fleet while saving MP.","s":[17]},{"h":"Fight <a href=\"#boss/tentacular\">Tentacular<\/a> (around 1345 HP), focusing the main body.","s":[17]},{"h":"Hit whichever tentacle shields the main body.","s":[17]},{"h":"Use <a href=\"#party/sylvando\">Hustle Dance<\/a> after its multi-hit attacks.","s":[17]},{"h":"Have Veronica cast <b>Kasap<\/b>.","s":[17]},{"h":"Have Veronica cast <b>Frizzle<\/b> with <b>Oomph<\/b> next.","s":[17]},{"h":"Use Serena&#x27;s <b>Kabuff<\/b> to soften party-wide hits.","s":[17]},{"h":"Get the veil from Kainui.","s":[17]},{"h":"Open the mini medal chest by Kainui&#x27;s house on Saikiki Beach.","s":[17]},{"h":"Give Michelle the veil at The Strand; telling the truth or lying both lead to <a href=\"#gear/item-lorelei-s-harp\">Lorelei&#x27;s Harp<\/a>.","s":[17]},{"h":"Sail into the vortex southwest of the Zwaardsrust dock.","s":[17]},{"h":"Play the harp there to reach Nautica.","s":[17]},{"h":"Open the chest behind the church for a mini medal.","s":[17]},{"h":"Speak to Queen Marina for the Green Orb.","s":[17]},{"h":"Finish <a href=\"#quests/up-where-they-walk\">Up Where They Walk<\/a> via the old man in Gondolia&#x27;s northwest tower and <a href=\"#quests/my-secret-saint\">My Secret Saint<\/a> with the figure on Insula Orientalis.","s":[17]}],"get_h":["Mini medal - The Strand, behind the western ship","Mini medal - Lonalulu, barrel south of the Tavern","<a href=\"#forge/book-crafting-comforting-clothing\">Crafting Comforting Clothing<\/a> - Insula Incognita, chest on top of the arch","<a href=\"#forge/book-my-first-pearly-pieces\">My First Pearly Pieces<\/a> - Lonalulu Armor shop bookshelf","<a href=\"#forge/book-building-a-blade-of-blistering-brutality\">Building a Blade of Blistering Brutality<\/a> - Lonalulu Weapons shop chest","<a href=\"#gear/item-lucida-shard\">Lucida Shard<\/a> - Insula Algarum, hidden northeast chest"],"source":[{"t":"The Green Orb / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/the-green-orb"}]},"a1-silver-orb":{"steps":[{"h":"Sail north from The Strand.","s":[18]},{"h":"Head inland to the east.","s":[18]},{"h":"Play the harp at the vortex.","s":[18]},{"h":"Open the chest in the corner west of the south camp for a mini medal.","s":[18]},{"h":"Mine the ore point east of the bridge for <a href=\"#gear/item-platinum-ore\">Platinum Ore<\/a>.","s":[18]},{"h":"Forge Drasilian pieces for the Luminary at the camp.","s":[18]},{"h":"Climb the rope east of the south bridge for a <a href=\"#gear/accessory-vanguard\">Vanguard<\/a>.","s":[18]},{"h":"Take the center stairs to an <a href=\"#gear/item-enchanted-stone\">Enchanted Stone<\/a>.","s":[18]},{"h":"At the Academie, accept <a href=\"#quests/making-things-right\">Making Things Right<\/a>.","s":[18]},{"h":"Forge the <a href=\"#gear/weapon-queen-s-whip\">Queen&#x27;s Whip<\/a> at +1 or higher for mini medals.","s":[18]},{"h":"Buy pearls from the woman in the first room at 100G each to rework gear.","s":[18]},{"h":"Search the Bibliotheque shelves for <a href=\"#forge/book-next-level-neckwear\">Next-Level Neckwear<\/a> and <a href=\"#forge/book-fine-and-dandy-designs\">Fine and Dandy Designs<\/a>.","s":[18]},{"h":"Accept <a href=\"#quests/a-memorial-mystery\">A Memorial Mystery<\/a>.","s":[18]},{"h":"Dig up the gold spot in the flowers southwest of the door at night.","s":[18]},{"h":"Accept <a href=\"#quests/the-agony-and-the-ecstasy\">The Agony and the Ecstasy<\/a> upstairs.","s":[18]},{"h":"Hand your medals to the Headmaster for <a href=\"#forge/book-kit-fit-for-a-king\">Kit Fit for a King<\/a>.","s":[18]},{"h":"In The Eerie Eyrie, ride a <b>Rotten Eggsoskeleton<\/b> to the ledge chests.","s":[18]},{"h":"Take the school paper from behind the cave sign.","s":[18]},{"h":"Ride a <b>Demonrider<\/b> up the claw-print wall.","s":[18]},{"h":"Go south for <a href=\"#forge/book-electrifying-equipment\">Electrifying Equipment<\/a>.","s":[18]},{"h":"Take <a href=\"#forge/book-build-better-birds-feet\">Build Better Birds&#x27; Feet<\/a> behind the waterfall and the chest with 4 <a href=\"#gear/item-magic-water\">Magic Water<\/a>.","s":[18]},{"h":"Heal up.","s":[18]},{"h":"Fight the <a href=\"#boss/elysium-bird\">Elysium bird<\/a> (over 800 HP) and two <a href=\"#boss/hades-condor\">Hades condor<\/a>s.","s":[18]},{"h":"Raise <b>Magic Barrier<\/b> and Hymn of Fire.","s":[18]},{"h":"If <a href=\"#party/veronica\">Veronica<\/a> is level 29 or higher, have her cast <b>Boom<\/b> on the whole enemy group.","s":[18]},{"h":"Kill the condors first.","s":[18]},{"h":"Keep damage steady through the bird&#x27;s heals.","s":[18]},{"h":"Open the final chest for the Silver Orb.","s":[18]},{"h":"Report back at the Academie.","s":[18]}],"get_h":["Mini medal - Champs Sauvage, west of the south camp","Mini medal - Eerie Eyrie, central stream chest","<a href=\"#forge/book-next-level-neckwear\">Next-Level Neckwear<\/a> - Academie Bibliotheque","<a href=\"#forge/book-fine-and-dandy-designs\">Fine and Dandy Designs<\/a> - Academie Bibliotheque","<a href=\"#forge/book-electrifying-equipment\">Electrifying Equipment<\/a> - Eerie Eyrie, west of the camp by the back route","<a href=\"#forge/book-build-better-birds-feet\">Build Better Birds&#x27; Feet<\/a> - behind the northern waterfall"],"source":[{"t":"The Silver Orb / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/the-silver-orb"}]},"a1-purple-orb":{"steps":[{"h":"Open the chest behind the market stall for a <a href=\"#gear/item-dragon-horn\">Dragon Horn<\/a>.","s":[19]},{"h":"Accept <a href=\"#quests/light-it-up\">Light it Up<\/a> south of the square.","s":[19]},{"h":"Ask the weather cow when it will rain.","s":[19]},{"h":"Rest until it rains.","s":[19]},{"h":"Beat a <b>Brollygagger<\/b> for the cloth.","s":[19]},{"h":"Buy Erik the <a href=\"#gear/weapon-sword-breaker\">Sword Breaker<\/a>.","s":[19]},{"h":"Read <a href=\"#forge/book-dragony-designs\">Dragony Designs<\/a> in the house south of the Weapons shop.","s":[19]},{"h":"Smash the pots on the top floor of the house east of the Armor shop for a mini medal.","s":[19]},{"h":"Follow the balcony of the house west of the church to a hidden chest with 10 pearls.","s":[19]},{"h":"Open the chest behind the ruins for <a href=\"#forge/book-knick-knacks-for-nifty-nickers\">Knick-Knacks for Nifty Nickers<\/a>.","s":[19]},{"h":"Talk to the woman with Bunny Ears upstairs at the Inn for a puff-puff and 5 Charm.","s":[19]},{"h":"Heal.","s":[19]},{"h":"Open the big chest on the east side path to fight the <b>Colossal Cannibox<\/b> (560 HP).","s":[19]},{"h":"Keep HP above 150.","s":[19]},{"h":"On the second visit, open the chests for a <a href=\"#gear/shield-platinum-platter\">Platinum Platter<\/a>, an <a href=\"#gear/item-enchanted-stone\">Enchanted Stone<\/a> and a mini medal.","s":[19]},{"h":"Level to 30 near the Goddess Statue.","s":[19]},{"h":"Add Serena if she has <a href=\"#party/serena\">Snap, Crackle, Poof<\/a>.","s":[19]},{"h":"Fight <a href=\"#boss/dora-in-grey\">Dora-in-Grey<\/a> (1,200 HP): Serena shields herself and the Luminary from charm, and <b>Hustle Dance<\/b> follows each laser.","s":[19]},{"h":"Deal damage with Jade&#x27;s <a href=\"#party/jade\">Multithrust<\/a> after Veronica&#x27;s <b>Oomphle<\/b>, plus <b>Sap<\/b> and the Luminary&#x27;s <a href=\"#party/hero\">Unbridled Blade<\/a>.","s":[19]},{"h":"Go down the eastern stairs in the Zwaardsrust ruins.","s":[19]},{"h":"Unlock the door for <a href=\"#forge/book-classy-clobber-for-kingly-kids\">Classy Clobber for Kingly Kids<\/a>, an <a href=\"#gear/item-enchanted-stone\">Enchanted Stone<\/a> and the Purple Orb.","s":[19]},{"h":"Take the gold sparkly spot in the same room for the <a href=\"#gear/item-choker\">Choker<\/a>.","s":[19]}],"get_h":["Mini medal - top-floor pot, house east of the Armor shop","Mini medal - Cursed Cloisters lower level chest","<a href=\"#forge/book-dragony-designs\">Dragony Designs<\/a> - bookshelf south of the Weapons shop","<a href=\"#forge/book-knick-knacks-for-nifty-nickers\">Knick-Knacks for Nifty Nickers<\/a> - chest behind the ruins","<a href=\"#gear/accessory-papillon-pendant\">Papillon Pendant<\/a> - from the Colossal Cannibox","<a href=\"#forge/book-classy-clobber-for-kingly-kids\">Classy Clobber for Kingly Kids<\/a> - Zwaardsrust ruins Magic Key room"],"source":[{"t":"The Purple Orb / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/the-purple-orb"}]},"a1-magic-key":{"steps":[{"h":"Open the northwest door on Insula Australis for a <a href=\"#gear/item-slime-crown\">Slime Crown<\/a>.","s":[20]},{"h":"Shoot the Emerald Coast targets.","s":[20]},{"h":"Report at the campsite for <a href=\"#gear/item-seed-of-magic\">Seed of Magic<\/a>s.","s":[20]},{"h":"Open the door southeast of your Cobblestone home for a <a href=\"#gear/accessory-wristorative\">Wristorative<\/a>, which heals 25 HP a turn at +3.","s":[20]},{"h":"Open the Downtown Heliodor door for 5000G.","s":[20]},{"h":"Open the door west of the Hotto Steppe ore point for a <a href=\"#gear/weapon-banishing-blade\">Banishing Blade<\/a>.","s":[20]},{"h":"Open the Gallopolis door by the Tavern for 2000G, <a href=\"#forge/book-making-the-magic-happen\">Making the Magic Happen<\/a>, a <a href=\"#gear/item-seed-of-skill\">Seed of Skill<\/a> and a mini medal.","s":[20]},{"h":"Open the Gondolia door by the Item shop for <a href=\"#forge/book-divine-designs\">Divine Designs<\/a>, a <a href=\"#gear/item-seed-of-magic\">Seed of Magic<\/a> and a mini medal.","s":[20]},{"h":"Open the tower door southwest of the Dundrasil camp for a stack of mini medals.","s":[20]},{"h":"Open the Puerto Valor door near the beach for a <a href=\"#gear/weapon-falcon-knife-earring\">Falcon Knife Earring<\/a>, Erik&#x27;s twin-strike dagger.","s":[20]},{"h":"Open the Lonalulu hilltop door for <a href=\"#gear/armor-zombie-mail\">Zombie Mail<\/a>, a mini medal and a <a href=\"#gear/item-seed-of-life\">Seed of Life<\/a>.","s":[20]},{"h":"Open the Academie door in the northwest of the first floor for a <a href=\"#gear/item-thunderball\">Thunderball<\/a>, a mini medal and a <a href=\"#gear/item-seed-of-skill\">Seed of Skill<\/a>.","s":[20]},{"h":"Open the Phnom Nonh door for <a href=\"#forge/book-secrets-of-the-silversmiths\">Secrets of the Silversmiths<\/a> and a <a href=\"#gear/item-sage-s-elixir\">Sage&#x27;s Elixir<\/a>.","s":[20]},{"h":"Open the north door on Insula Occidentalis for a <a href=\"#gear/weapon-falcon-blade\">Falcon Blade<\/a>.","s":[20]},{"h":"Sail through the vortex east of Insula Borealis to Insula Centralis for a mini medal, the last target and a <a href=\"#gear/item-sainted-soma\">Sainted Soma<\/a>.","s":[20]},{"h":"Report on Insula Occidentalis.","s":[20]}],"get_h":["Mini medal - Gallopolis, Gondolia and Lonalulu Magic Key rooms","Mini medal - Dundrasil tower Magic Key room","<a href=\"#forge/book-making-the-magic-happen\">Making the Magic Happen<\/a> - Gallopolis Magic Key room","<a href=\"#forge/book-divine-designs\">Divine Designs<\/a> - Gondolia Magic Key room","<a href=\"#forge/book-secrets-of-the-silversmiths\">Secrets of the Silversmiths<\/a> - Phnom Nonh Magic Key room","<a href=\"#gear/accessory-wristorative\">Wristorative<\/a> - Cobblestone Magic Key room"],"source":[{"t":"The Magic Key / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/the-magic-key"}]},"a1-blue-orb":{"steps":[{"h":"Grab the <a href=\"#gear/item-magic-beast-hide\">Magic Beast Hide<\/a> from the pier barrels.","s":[21]},{"h":"Rest at the camp behind the city.","s":[21]},{"h":"Forge the <a href=\"#gear/weapon-hocus-locus\">Hocus Locus<\/a> for Veronica and Rab, buying any missing <a href=\"#gear/item-silkblossom\">Silkblossom<\/a> from the camp merchant.","s":[21]},{"h":"Unlock the Magic Key door at the back to enter the frozen city.","s":[21]},{"h":"Talk to the Queen.","s":[21]},{"h":"Open the cabin chest northwest of the city for a mini medal.","s":[21]},{"h":"Ride a <b>Face Invader<\/b> in the Snaerfelt.","s":[21]},{"h":"Ram the ice blocks by holding R2.","s":[21]},{"h":"Cross the western archway for a mini medal chest.","s":[21]},{"h":"Take <a href=\"#forge/book-supercool-kit\">Supercool Kit<\/a> from behind the cabin by the Hekswood.","s":[21]},{"h":"In the Hekswood, follow the western ice path south to <a href=\"#forge/book-platinum-protection\">Platinum Protection<\/a>.","s":[21]},{"h":"Fight <a href=\"#boss/j-rmun\">Jörmun<\/a> (820 HP) solo.","s":[21]},{"h":"Keep HP above 100.","s":[21]},{"h":"Use <b>Unbridled Blade<\/b> after its jig drops its defence.","s":[21]},{"h":"Hit switches in the Royal Library to move shelves.","s":[21]},{"h":"Take both recipe books from the Level 3 shelves.","s":[21]},{"h":"Kill the <b>Mimic<\/b> (around 720 HP) on Level 4 quickly with <b>Sap<\/b>, <b>Unbridled Blade<\/b> and <a href=\"#party/jade\">Multithrust<\/a> before it uses <b>Thwack<\/b>.","s":[21]},{"h":"Fight <a href=\"#boss/krystalinda\">Krystalinda<\/a> (1800 HP).","s":[21]},{"h":"Raise <b>Magic Barrier<\/b>.","s":[21]},{"h":"Cast <b>Sap<\/b> on her.","s":[21]},{"h":"Cast <b>Oomph<\/b> on the Luminary and Jade.","s":[21]},{"h":"Keep <a href=\"#party/sylvando\">Hustle Dance<\/a> going.","s":[21]},{"h":"Take the <a href=\"#gear/weapon-nobleman-s-knife\">Nobleman&#x27;s Knife<\/a> for Erik and the basement mini medal in the castle.","s":[21]},{"h":"Get the Blue Orb.","s":[21]},{"h":"Accept <a href=\"#quests/the-viking-hoard\">The Viking Hoard<\/a>.","s":[21]},{"h":"Accept <a href=\"#quests/a-cold-crush\">A Cold Crush<\/a>.","s":[21]},{"h":"Read the Inn bookshelf for <a href=\"#forge/book-platinum-power\">Platinum Power<\/a>.","s":[21]},{"h":"Pick the gold Snaerose south of the Snaerfelt camp for <a href=\"#forge/book-that-s-magic\">That&#x27;s Magic<\/a>.","s":[21]},{"h":"Bring the Viking&#x27;s gift from Insula Borealis.","s":[21]}],"get_h":["Mini medal - cabin chest northwest of the city","Mini medal - Snaerfelt chest across the archway","Mini medal - Sniflheim Castle basement pot","<a href=\"#forge/book-supercool-kit\">Supercool Kit<\/a> - behind the cabin near the Hekswood","<a href=\"#forge/book-favourite-fashions-of-the-masters-of-magic\">Favourite Fashions of the Masters of Magic<\/a> - Royal Library Level 3","<a href=\"#forge/book-an-anthology-of-elemental-earrings\">An Anthology of Elemental Earrings<\/a> - Royal Library Level 3"],"source":[{"t":"The Blue Orb / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/the-blue-orb"}]},"a1-yggdrasil":{"steps":[{"h":"Ride a <b>Runny Eggsoskeleton<\/b> up the Pit Cave to the chest with a mini medal.","s":[22]},{"h":"Loot Arboria: the mini medal chest by the entrance stairs, the <a href=\"#gear/accessory-supplicant\">Supplicant<\/a> upstairs in the twins&#x27; house and the Item shop <a href=\"#gear/item-sainted-soma\">Sainted Soma<\/a>.","s":[22]},{"h":"Accept <a href=\"#quests/fit-as-a-fiddle\">Fit as a Fiddle<\/a> from the old man and <a href=\"#quests/planting-seeds-for-the-future\">Planting Seeds for the Future<\/a> in the Grove of Repose.","s":[22]},{"h":"Zoom to the Academie.","s":[22]},{"h":"Trade medals for the <a href=\"#gear/armor-agility-gilet\">Agility Gilet<\/a> and <a href=\"#gear/armor-glombolero\">Glombolero<\/a>.","s":[22]},{"h":"Shoot the Manglegrove targets.","s":[22]},{"h":"Report to the camp bowyer.","s":[22]},{"h":"See Bo in Gallopolis for the <a href=\"#gear/headwear-happy-hat\">Happy Hat<\/a>.","s":[22]},{"h":"Open the chest north of the first fork in the Arborian Highlands for a mini medal.","s":[22]},{"h":"Forge a <a href=\"#gear/weapon-platinum-lance\">Platinum Lance<\/a> for Jade at the camp.","s":[22]},{"h":"Rework any pieces you are equipping that are not at +3.","s":[22]},{"h":"Open the cave chest in the First Forest for <a href=\"#forge/book-how-to-outdo-the-undead\">How to Outdo the Undead<\/a>.","s":[22]},{"h":"Pick the gold sparkly spot under the large northern tree for the Red Kale.","s":[22]},{"h":"Fight <b>Sprite Bulb<\/b>s near the top until a <b>Wight Bulb<\/b> appears and drops the seeds.","s":[22]},{"h":"Zoom to Arboria.","s":[22]},{"h":"Turn in both quests for a <a href=\"#gear/accessory-healer\">Healer<\/a> and a <a href=\"#gear/weapon-butterfly-baton\">Butterfly Baton<\/a>.","s":[22]},{"h":"Use the well at the World Tree to return to the great altar.","s":[22]},{"h":"Open the chest behind the altar for a mini medal.","s":[22]},{"h":"Pick up the <a href=\"#gear/item-yggdrasil-dew\">Yggdrasil Dew<\/a>.","s":[22]},{"h":"Keep the <a href=\"#gear/item-yggdrasil-dew\">Yggdrasil Dew<\/a> for emergencies.","s":[22]},{"h":"Against <a href=\"#boss/jasper\">Jasper<\/a> at the Heart of Yggdrasil, use only buffs and healing; the fight cannot be won.","s":[22]}],"get_h":["Mini medal - Pit Cave chest","Mini medal - Arboria, chest south of the entrance stairs","Mini medal - Arborian Highlands, north chest","Mini medal - First Forest, behind the great altar","<a href=\"#forge/book-how-to-outdo-the-undead\">How to Outdo the Undead<\/a> - First Forest cave chest","<a href=\"#gear/headwear-happy-hat\">Happy Hat<\/a> - Bo, for every crossbow target"],"source":[{"t":"Onward to Yggdrasil / Act I / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-i/onward-to-yggdrasil"}]},"i-sylvando":{"steps":[{"h":"Note that only the items <a href=\"#party/sylvando\">Sylvando<\/a> carried are usable.","s":[23]},{"h":"Skip the shops, since your forged gear beats their stock.","s":[23]},{"h":"Talk to the man standing by the water at the stage in the north of Gondolia.","s":[23]},{"h":"Talk to the Beastly Boys at the stall just left of the town entrance.","s":[23]},{"h":"Beat the Beastly Boys, hitting the left one first because he raises their attack.","s":[23]},{"h":"Return the knapsack to the man by the water.","s":[23]},{"h":"Leave for the Gallopolis Region, ignoring the way to Grotta della Fonte.","s":[23]},{"h":"In the Laguna di Gondolia cave, talk to the cow beside it.","s":[23]},{"h":"Bring the milk to the tired priest so he joins.","s":[23]},{"h":"Go to the peninsula south of Gallopolis.","s":[23]},{"h":"Fight the Vicious <b>Fandangow<\/b> group there for the knight.","s":[23]},{"h":"Lean on the priest&#x27;s <a href=\"#party/hero\">Midheal<\/a> if their dance costs turns.","s":[23]},{"h":"If the <b>Cactolotl<\/b> surfaces on that peninsula, walk away; it is far stronger than your group.","s":[23]},{"h":"In Gallopolis, talk to the juggler in the southeastern tavern.","s":[23]},{"h":"Pick the red ball.","s":[23]},{"h":"Talk to the drummer outside the church.","s":[23]},{"h":"Cheer up Margarita at the stables north of him.","s":[23]},{"h":"Keep the horse poo she gives you.","s":[23]},{"h":"Talk to the man outside the circus tent.","s":[23]},{"h":"Watch the show.","s":[23]},{"h":"Save.","s":[23]},{"h":"Head out to the Hotto Steppe.","s":[23]},{"h":"Give the horse poo to the man with the plant monster north of the Slime so he joins.","s":[23]},{"h":"Rest at the camp past the north bridge.","s":[23]},{"h":"Save at the camp.","s":[23]},{"h":"Fight the <b>Gigantes<\/b> guarding the bridge to the east.","s":[23]},{"h":"Put the <b>Gigantes<\/b> to sleep with the priest&#x27;s sermon.","s":[23]},{"h":"Heal with <a href=\"#party/sylvando\">Hustle Dance<\/a> after Crackerwhack, which hits everyone for around 80.","s":[23]},{"h":"Enter Hotto to end the interlude; if you missed a recruit, the best outfit can still be earned later.","s":[23]}],"get_h":[],"source":[{"t":"In Search of Hope / Character Interludes / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/character-interludes/in-search-of-hope"}]},"i-jade":{"steps":[{"h":"Skip the Vicious <a href=\"#boss/great-sabrecat\">Great Sabrecat<\/a> packs outside Octagonia; you can fill their entries later.","s":[24]},{"h":"Save at the Goddess statue.","s":[24]},{"h":"Climb to the third level to meet <a href=\"#boss/booga\">Booga<\/a>.","s":[24]},{"h":"If lost, use the path beside the monster with the pink bubble.","s":[24]},{"h":"In the Limboo cells, smash the southeastern cell pots for a <a href=\"#gear/item-rockbomb-shard\">Rockbomb Shard<\/a>.","s":[24]},{"h":"Smash the north-central cell pots for a <a href=\"#gear/item-special-medicine\">Special Medicine<\/a>.","s":[24]},{"h":"Save with the big guy in the northeastern cell.","s":[24]},{"h":"Enter the southwestern cell to continue.","s":[24]},{"h":"Put the prisoner&#x27;s free items into <a href=\"#party/jade\">Jade<\/a>&#x27;s inventory.","s":[24]},{"h":"Talk to the knight guarding the exit to start the gauntlet.","s":[24]},{"h":"In the first fight, use <b>Party Pooper<\/b> on all three attackers; the <a href=\"#gear/armor-hare-raising-suit\">Hare-Raising Suit<\/a> revives you, but winning gives experience.","s":[24]},{"h":"In the second fight, kill the Boodiful Wizards first, since their <a href=\"#party/hero\">Frizzle<\/a> deals 60 or more.","s":[24]},{"h":"In the third fight, wipe out one pair quickly so they cannot pep up for Just Claws.","s":[24]},{"h":"Against <a href=\"#boss/boodica\">Boodica<\/a>, use <a href=\"#party/jade\">Multithrust<\/a> on her two hands (about 350 HP each) before anything else.","s":[24]},{"h":"Then wear <a href=\"#boss/boodica\">Boodica<\/a> down (about 1600 HP) while <a href=\"#boss/sinderella\">Sinderella<\/a> heals with <a href=\"#party/hero\">Midheal<\/a> and powers you up with <b>Oomph<\/b>.","s":[24]}],"get_h":["<a href=\"#gear/item-special-medicine\">Special Medicine<\/a> x3, <a href=\"#gear/item-magic-water\">Magic Water<\/a>, <a href=\"#gear/item-rockbomb-shard\">Rockbomb Shard<\/a> - from a prisoner on the walk to the gauntlet"],"source":[{"t":"Jade Journeys Forth / Character Interludes / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/character-interludes/jade-journeys-forth"}]},"i-erik":{"steps":[{"h":"Leave the cell.","s":[25]},{"h":"Take the southeast exit.","s":[25]},{"h":"Open the chest for a <a href=\"#gear/weapon-steel-broadsword\">Steel Broadsword<\/a>.","s":[25]},{"h":"Crawl through the gap.","s":[25]},{"h":"Listen at the wall crack to learn the key sits in the middle chest.","s":[25]},{"h":"At the five-chest dead end, beat the <b>Cannibox<\/b> chests in the northwest and southeast for a <a href=\"#gear/item-seed-of-skill\">Seed of Skill<\/a> each.","s":[25]},{"h":"Open the middle chest for the <b>Hideout Key<\/b>, plus the southwest and northeast chests for gear.","s":[25]},{"h":"Unlock the north door in the first room.","s":[25]},{"h":"Keep north, following the upper ledge to the crawl hole into the Ancient Ruins.","s":[25]},{"h":"Ride the ornate platform across the chasm.","s":[25]},{"h":"Save at the statue, which also refills HP and MP.","s":[25]},{"h":"Clear the three monster groups at the dead lift.","s":[25]},{"h":"Watch for <b>Bobonga<\/b> fire breath (around 70) and <b>Professaurus<\/b> <a href=\"#party/hero\">Frizzle<\/a> there.","s":[25]},{"h":"Ride the powered lift.","s":[25]},{"h":"Open the ledge chests for a <a href=\"#gear/item-seed-of-deftness\">Seed of Deftness<\/a> and an <a href=\"#gear/accessory-agility-ring\">Agility Ring<\/a>.","s":[25]},{"h":"In the Great Hall, climb the western wooden platform for the <a href=\"#gear/headwear-disturbin-turban\">Disturbin&#x27; Turban<\/a> chest.","s":[25]},{"h":"Exit north.","s":[25]},{"h":"Defeat the Vicious <b>Chihuawyrm<\/b> first.","s":[25]},{"h":"Defeat the <b>Skelegon<\/b> next.","s":[25]},{"h":"Defeat the <b>Dragon Rider<\/b> last.","s":[25]},{"h":"Fight <a href=\"#boss/indignus\">Indignus<\/a>; your boosted regeneration makes losing unlikely, so pair <a href=\"#party/erik\">Divide<\/a> with ailment skills for big damage.","s":[25]}],"get_h":["<a href=\"#gear/item-seed-of-skill\">Seed of Skill<\/a> x2 - Canniboxes in the five-chest room","<a href=\"#gear/accessory-agility-ring\">Agility Ring<\/a> - ledge chest past the big lift"],"source":[{"t":"Erik's New Acquaintance / Character Interludes / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/character-interludes/eriks-new-acquaintance"}]},"i-rab":{"steps":[{"h":"Chase the bunny girl.","s":[26]},{"h":"Talk to the bunny girl to move to old Dundrasil.","s":[26]},{"h":"Go to the throne room.","s":[26]},{"h":"Sit on the left throne.","s":[26]},{"h":"Answer yes when asked.","s":[26]},{"h":"Search the cabinets in the room north of the throne room for a <a href=\"#gear/item-sage-s-elixir\">Sage&#x27;s Elixir<\/a>.","s":[26]},{"h":"Talk to Irwin outside the throne room.","s":[26]},{"h":"Sit on the throne.","s":[26]},{"h":"Answer the audiences however you like.","s":[26]},{"h":"Answer the trivia man by the saving priest with True, False, True, False, True for a <a href=\"#gear/item-seed-of-magic\">Seed of Magic<\/a>.","s":[26]},{"h":"Take the western garden guard&#x27;s posy to any red-haired person in green for a <a href=\"#gear/item-pretty-betsy\">Pretty Betsy<\/a>.","s":[26]},{"h":"Bring the well-dressed man in the east middle-floor room any pungent item (the pie or a plant) for a <a href=\"#gear/item-seed-of-strength\">Seed of Strength<\/a>.","s":[26]},{"h":"Talk to Irwin in the middle-floor garden.","s":[26]},{"h":"Check the throne-room cupboards for a <a href=\"#gear/item-dieamend\">Dieamend<\/a>.","s":[26]},{"h":"Follow the bunny girl to the southern stairs.","s":[26]},{"h":"Smash the corner pots in the room below for <a href=\"#gear/item-wakerobin\">Wakerobin<\/a>s.","s":[26]},{"h":"Talk to the young <a href=\"#party/hero\">Luminary<\/a> at each stop.","s":[26]},{"h":"Answer the bunny girl yes twice.","s":[26]},{"h":"Go up through the door.","s":[26]},{"h":"Fight <a href=\"#boss/grand-master-pang\">Grand Master Pang<\/a> (losing still lets the story continue).","s":[26]},{"h":"Put her to sleep with <a href=\"#party/hero\">Snooze<\/a>.","s":[26]},{"h":"Attack with <b>Zammle<\/b>.","s":[26]},{"h":"Heal with <a href=\"#party/hero\">Moreheal<\/a>.","s":[26]},{"h":"Kill her <b>Tantamount<\/b> (about 320 HP) fast.","s":[26]},{"h":"Defend after her second charge to soften the 11-hit attack.","s":[26]}],"get_h":["<a href=\"#gear/item-seed-of-magic\">Seed of Magic<\/a> - trivia man near the saving priest","<a href=\"#gear/item-seed-of-strength\">Seed of Strength<\/a> - pepper errand, east middle-floor room","<a href=\"#gear/item-pretty-betsy\">Pretty Betsy<\/a> - posy errand"],"source":[{"t":"Lord Robert and the Kingdom of Dreams / Character Interludes / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/character-interludes/lord-robert-and-the-kingdom-of-dreams"}]},"a2-dawn":{"steps":[{"h":"Swim around Nautica before seeing the Queen; chests hold a <a href=\"#gear/item-seed-of-skill\">Seed of Skill<\/a>, <a href=\"#gear/item-elfin-elixir\">Elfin Elixir<\/a>, <a href=\"#gear/weapon-zombiesbane\">Zombiesbane<\/a> and a mini medal north of the item shop.","s":[27]},{"h":"Talk to Queen Marina in the Palace.","s":[27]},{"h":"Touch the pearl.","s":[27]},{"h":"Grab the juicy prawn in the centre of town.","s":[27]},{"h":"On the Emerald Coast, rest at the camp to re-register Zoom.","s":[27]},{"h":"Go through Cobblestone Falls.","s":[27]},{"h":"In The Last Bastion, climb the ladder at the far west past the weapon shop for a 3000G chest.","s":[27]},{"h":"Meet the King in the Royal Tent.","s":[27]},{"h":"Join <a href=\"#party/hendrik\">Hendrik<\/a> at the north barricade.","s":[27]},{"h":"Against the <a href=\"#boss/headless-honcho\">Headless Honcho<\/a>, kill the <a href=\"#boss/vicious-grim-gryphon\">Vicious Grim Gryphon<\/a> first.","s":[27]},{"h":"Clear the escorts with <a href=\"#party/hero\">Boom<\/a> and <a href=\"#party/hero\">Kasnooze<\/a>.","s":[27]},{"h":"Then hit the Honcho (about 690 HP) with <b>Unbridled Blade<\/b>, keeping HP above 150.","s":[27]},{"h":"Take the <a href=\"#gear/item-sewer-key\">Sewer Key<\/a> from the King.","s":[27]},{"h":"Climb the northwest vine in the Heliodorian Foothills to the secret sewer entrance.","s":[27]},{"h":"If you want revenge on the <b>Black Dragon<\/b>, take the north path in the sewers.","s":[27]},{"h":"Beat the <b>Black Dragon<\/b> (about 1050 HP) with <b>Unbridled Blade<\/b>.","s":[27]},{"h":"In Heliodor Castle, search Jasper&#x27;s Quarters for a <a href=\"#gear/weapon-platinum-sword\">Platinum Sword<\/a> and <a href=\"#forge/book-the-devil-s-in-the-details\">The Devil&#x27;s in the Details<\/a>.","s":[27]},{"h":"Move the southern shelves in the storage room past the kitchen to reach the bedchambers and their recipe books.","s":[27]},{"h":"Fight <a href=\"#boss/tyriant\">Tyriant<\/a>.","s":[27]},{"h":"Kill each Shadow (about 280 HP) with <b>Unbridled Blade<\/b>.","s":[27]},{"h":"Use magic during Sword Stance.","s":[27]},{"h":"Keep HP above 150.","s":[27]},{"h":"Zoom to The Last Bastion.","s":[27]},{"h":"Go down the western stairs in the Cobblestone Tor caverns for <a href=\"#forge/book-footwear-of-the-rich-and-famous\">Footwear of the Rich and Famous<\/a>.","s":[27]},{"h":"Talk to the King for the <a href=\"#gear/shield-shield-of-heliodor\">Shield of Heliodor<\/a>.","s":[27]},{"h":"Save at the church.","s":[27]},{"h":"Set out for the Manglegrove.","s":[27]}],"get_h":["<a href=\"#forge/book-the-devil-s-in-the-details\">The Devil&#x27;s in the Details<\/a> - Jasper&#x27;s Quarters bookshelf, Heliodor Castle","<a href=\"#forge/book-a-recipe-book-of-regal-regalia\">A Recipe Book of Regal Regalia<\/a> - King&#x27;s Bedchamber bookshelf","<a href=\"#forge/book-little-lifesavers\">Little Lifesavers<\/a> - Queen&#x27;s Bedchamber chest","<a href=\"#forge/book-footwear-of-the-rich-and-famous\">Footwear of the Rich and Famous<\/a> - Cobblestone Tor caverns, end of western stairs","<a href=\"#gear/weapon-platinum-sword\">Platinum Sword<\/a> - Jasper&#x27;s Quarters chest","<a href=\"#gear/shield-shield-of-heliodor\">Shield of Heliodor<\/a> - from the King after Heliodor is freed"],"source":[{"t":"Dawn of a New World / Act II / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-ii/dawn-of-a-new-world"}]},"a2-angri-la":{"steps":[{"h":"In the Manglegrove, take the vine down to the southwest.","s":[28]},{"h":"Open the chest to the north for a mini medal.","s":[28]},{"h":"At the Manglegrove camp, forge a <a href=\"#gear/weapon-king-axe\">King Axe<\/a> for <a href=\"#party/hendrik\">Hendrik<\/a> (or upgrade his axe) and <a href=\"#gear/armor-magic-armor\">Magic Armour<\/a> at +3.","s":[28]},{"h":"Rework the <a href=\"#gear/shield-shield-of-heliodor\">Shield of Heliodor<\/a> to +3.","s":[28]},{"h":"Forge a <a href=\"#gear/accessory-shield-bearer\">Shield-Bearer<\/a>.","s":[28]},{"h":"Equip the Shield-Bearer on <a href=\"#party/hendrik\">Hendrik<\/a>.","s":[28]},{"h":"Cross to the Costa Valor.","s":[28]},{"h":"Head north into Mount Pang Lai, ignoring the landslide.","s":[28]},{"h":"In the Base Cave, beat a glittering <b>Dragon Rider<\/b>.","s":[28]},{"h":"Fly the <b>Dragon Rider<\/b> across the water to the <a href=\"#gear/item-mythril-ore\">Mythril Ore<\/a> spots.","s":[28]},{"h":"On the Slopes, open the chest past the bridge for <a href=\"#forge/book-more-dragony-designs\">More Dragony Designs<\/a>.","s":[28]},{"h":"Open the chest east of town for a <a href=\"#gear/weapon-staff-of-antimagic\">Staff of Antimagic<\/a>.","s":[28]},{"h":"In Angri-La, buy <a href=\"#gear/item-dragon-hide\">Dragon Hide<\/a>s and <a href=\"#gear/item-dragon-horn\">Dragon Horn<\/a>s at the item shop.","s":[28]},{"h":"If you lacked materials for the <a href=\"#gear/weapon-king-axe\">King Axe<\/a>, buy an <a href=\"#gear/weapon-ice-axe\">Ice Axe<\/a>.","s":[28]},{"h":"Meet the High Lama in the High Hall.","s":[28]},{"h":"Follow the High Lama east to the Field of Discipline.","s":[28]},{"h":"Next morning, accept <a href=\"#quests/understanding-angri-la\">Understanding Angri-La<\/a> near the priest.","s":[28]},{"h":"Finish a <b>Boreal Serpent<\/b> with <b>Blaze of Glory<\/b> for a <a href=\"#gear/accessory-mystic\">Mystic<\/a>.","s":[28]},{"h":"In the Summit Tunnel, fly a <b>Dragon Rider<\/b> to the northwest lake island for a <a href=\"#gear/accessory-sorcerer-s-ring\">Sorcerer&#x27;s Ring<\/a>.","s":[28]},{"h":"At the summit camp, forge the <a href=\"#gear/weapon-wyrmfang\">Wyrmfang<\/a> for the <a href=\"#party/hero\">Luminary<\/a>.","s":[28]},{"h":"Rework the <a href=\"#gear/weapon-ice-axe\">Ice Axe<\/a> if you bought one.","s":[28]},{"h":"Rest at the camp.","s":[28]},{"h":"Save.","s":[28]},{"h":"Spar with <a href=\"#party/rab\">Rab<\/a> by casting <b>Quadraslash<\/b> every turn; the aim is to power it up, not to beat him.","s":[28]},{"h":"Defend the turn after <a href=\"#party/rab\">Rab<\/a> prepares himself to soften <b>Pearly Gates<\/b>.","s":[28]},{"h":"Use <a href=\"#party/hero\">Moreheal<\/a> if HP drops below 150.","s":[28]},{"h":"Leave the Wheel of Harma at the Field of Discipline alone until your party is around level 50.","s":[28]}],"get_h":["<a href=\"#forge/book-more-dragony-designs\">More Dragony Designs<\/a> - Mount Pang Lai Slopes, chest past the bridge","<a href=\"#gear/weapon-staff-of-antimagic\">Staff of Antimagic<\/a> - Mount Pang Lai Slopes, east of town","<a href=\"#gear/accessory-sorcerer-s-ring\">Sorcerer&#x27;s Ring<\/a> - Summit Tunnel lake island","<a href=\"#gear/accessory-mystic\">Mystic<\/a> - <a href=\"#quests/understanding-angri-la\">Understanding Angri-La<\/a> reward","<a href=\"#gear/item-ethereal-stone\">Ethereal Stone<\/a> - Angri-La inn chest"],"source":[{"t":"Journey to Angri-La / Act II / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-ii/journey-to-angri-la"}]},"a2-sylvando":{"steps":[{"h":"Zoom to the Mount Pang Lai campsite.","s":[29]},{"h":"Return to the Costa Valor.","s":[29]},{"h":"Take the new passage west into the Champs Sauvage.","s":[29]},{"h":"Mount a glittering <b>Honeyhead Horknight<\/b> near L&#x27;Academie.","s":[29]},{"h":"Fly over the lake to a chest with a <a href=\"#gear/item-sunny-citrine\">Sunny Citrine<\/a>.","s":[29]},{"h":"Accept <a href=\"#quests/madame-labouche-s-life-lesson\">Madame Labouche&#x27;s Life Lesson<\/a> from the Lips outside L&#x27;Academie; it needs 330 Charm.","s":[29]},{"h":"Inside, accept <a href=\"#quests/a-delayed-diploma\">A Delayed Diploma<\/a>.","s":[29]},{"h":"Accept <a href=\"#quests/a-fragrant-fille\">A Fragrant Fille<\/a>.","s":[29]},{"h":"At night in the northeast classroom, accept <a href=\"#quests/one-last-request\">One Last Request<\/a>.","s":[29]},{"h":"Trade your mini medals with the Headmaster for <a href=\"#gear/armor-spiked-armor\">Spiked Armour<\/a> and the <a href=\"#gear/weapon-miracle-sword\">Miracle Sword<\/a>.","s":[29]},{"h":"Accept <a href=\"#quests/a-right-riddle\">A Right Riddle<\/a> in the Bibliotheque.","s":[29]},{"h":"Equip a <a href=\"#gear/weapon-steel-broadsword\">Steel Broadsword<\/a>, forging one if needed, to pass the first riddle.","s":[29]},{"h":"Cross the large bridge south toward Phnom Nonh and escort Da home with the troupe.","s":[29]},{"h":"In Phnom Nonh, accept <a href=\"#quests/worth-its-salt\">Worth Its Salt<\/a>.","s":[29]},{"h":"Rest at the inn.","s":[29]},{"h":"Register the nearby camp.","s":[29]},{"h":"Swap the <a href=\"#gear/armor-mardi-garb\">Mardi Garb<\/a> for real armour to raise defence.","s":[29]},{"h":"Go south to the Promontory Cave.","s":[29]},{"h":"Fight <a href=\"#boss/avarith\">Avarith<\/a> (about 2200 HP).","s":[29]},{"h":"Have <a href=\"#party/rab\">Rab<\/a> cast <a href=\"#party/rab\">Antimagic<\/a> to stop <b>Kasizz<\/b>.","s":[29]},{"h":"Heal with <b>Staff of Salvation<\/b> and <b>Right as Rain<\/b>.","s":[29]},{"h":"Lower her defence with <b>Helm Splitter<\/b>.","s":[29]},{"h":"Hit with <b>Unbridled Blade<\/b>.","s":[29]},{"h":"Cast <b>Multiheal<\/b> whenever your spells are unsealed.","s":[29]},{"h":"Zoom back.","s":[29]},{"h":"Meet <a href=\"#party/sylvando\">Sylvando<\/a> on the hill.","s":[29]},{"h":"Take the Costa Valor east tunnel to Puerto Valor.","s":[29]},{"h":"Before leaving Don Rodrigo&#x27;s house, take <a href=\"#forge/book-platinum-plating\">Platinum Plating<\/a> from the bookshelf.","s":[29]},{"h":"Take a <a href=\"#gear/item-finessence\">Finessence<\/a> from the right wardrobe.","s":[29]},{"h":"Accept <a href=\"#quests/when-knight-falls\">When Knight Falls<\/a> near the entrance.","s":[29]},{"h":"Buy <a href=\"#forge/book-the-mothmask-prophecies\">The Mothmask Prophecies<\/a> at the casino, since it is a one-time prize.","s":[29]}],"get_h":["<a href=\"#gear/armor-spiked-armor\">Spiked Armour<\/a>, <a href=\"#gear/weapon-miracle-sword\">Miracle Sword<\/a> - mini medal rewards at L&#x27;Academie","<a href=\"#forge/book-platinum-plating\">Platinum Plating<\/a> - Don Rodrigo&#x27;s bookshelf, Puerto Valor","<a href=\"#gear/item-finessence\">Finessence<\/a> - Don Rodrigo&#x27;s right wardrobe","<a href=\"#forge/book-the-mothmask-prophecies\">The Mothmask Prophecies<\/a> - Puerto Valor casino prize","<a href=\"#gear/item-sunny-citrine\">Sunny Citrine<\/a> - Champs Sauvage lake chest, needs a mount"],"source":[{"t":"Reuniting with Sylvando / Act II / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-ii/reuniting-with-sylvando"}]},"a2-jade":{"steps":[{"h":"Board the ship in the Costa Valor.","s":[30]},{"h":"Sail northwest to the Zwaardsrust Region, leaving Gondolia for later.","s":[30]},{"h":"Find the small gravestone in the hay fields southeast of the Warrior&#x27;s Rest Inn.","s":[30]},{"h":"Return to the girl from Quest 32 for a <a href=\"#gear/item-chronocrystal\">Chronocrystal<\/a>.","s":[30]},{"h":"Rework the <a href=\"#gear/armor-mardi-garb\">Mardi Garb<\/a> to +3 to hit 330 Charm.","s":[30]},{"h":"Finish <a href=\"#quests/madame-labouche-s-life-lesson\">Madame Labouche&#x27;s Life Lesson<\/a> for <a href=\"#forge/book-glam-gear-for-go-getters\">Glam Gear for Go-Getters<\/a>.","s":[30]},{"h":"Register the Dundrasil Region camp.","s":[30]},{"h":"Switch to night.","s":[30]},{"h":"Ride a glittering <b>Headless Horseman<\/b> for the mount trophy.","s":[30]},{"h":"Enter the castle ruins through the well.","s":[30]},{"h":"Follow <a href=\"#party/rab\">Rab<\/a>&#x27;s secret passage to the <a href=\"#gear/item-sage-s-elixir\">Sage&#x27;s Elixir<\/a> chest at the intersection.","s":[30]},{"h":"Fight the <a href=\"#boss/restless-knight\">Restless Knight<\/a> (about 2400 HP).","s":[30]},{"h":"Have <a href=\"#party/rab\">Rab<\/a> cast <b>Blunt<\/b> and <b>Sap<\/b>.","s":[30]},{"h":"Have <a href=\"#party/rab\">Rab<\/a> lift curses.","s":[30]},{"h":"Keep <b>Blunt<\/b> on the knight if he peps up.","s":[30]},{"h":"Have <a href=\"#party/sylvando\">Sylvando<\/a> use <b>Oomph<\/b> on the <a href=\"#party/hero\">Luminary<\/a>.","s":[30]},{"h":"Hit with <b>Unbridled Blade<\/b> for over 600 each.","s":[30]},{"h":"In past Dundrasil, follow the King into the tunnels.","s":[30]},{"h":"Use <b>Quadraslash<\/b> on the monster group.","s":[30]},{"h":"Fight the <a href=\"#boss/gloomnivore\">Gloomnivore<\/a> (about 2750 HP).","s":[30]},{"h":"Use <b>Blunt<\/b> on its attack.","s":[30]},{"h":"Paralyse it with <a href=\"#party/hendrik\">Parallax<\/a>.","s":[30]},{"h":"Heal with <a href=\"#party/sylvando\">Hustle Dance<\/a>.","s":[30]},{"h":"In Octagonia&#x27;s casino, take the 2000 free tokens.","s":[30]},{"h":"Spend your winnings on <a href=\"#gear/item-love-potion\">Love Potion<\/a>s, the only useful prize.","s":[30]},{"h":"Load MP restoring items on <a href=\"#party/rab\">Rab<\/a>, the <a href=\"#party/hero\">Luminary<\/a> and <a href=\"#party/sylvando\">Sylvando<\/a>.","s":[30]},{"h":"Give the Dracky by the stairs a <a href=\"#gear/item-love-potion\">Love Potion<\/a> to enter the VIP area.","s":[30]},{"h":"Fight <a href=\"#boss/jinxed-jade\">Jinxed Jade<\/a> (about 1800 HP).","s":[30]},{"h":"Cast <b>Sap<\/b> on her.","s":[30]},{"h":"Give the <a href=\"#party/hero\">Luminary<\/a> <b>Oomphle<\/b> for <a href=\"#party/hero\">Unbridled Blade<\/a>.","s":[30]},{"h":"Keep HP high against Sexy Beam.","s":[30]},{"h":"Fight <a href=\"#boss/booga\">Booga<\/a> right after (about 3200 HP).","s":[30]},{"h":"Use <a href=\"#party/sylvando\">Sobering Slap<\/a> on charmed allies.","s":[30]},{"h":"Keep <b>Blunt<\/b> and <b>Sap<\/b> on him.","s":[30]},{"h":"Use MP items freely.","s":[30]},{"h":"If you want the <a href=\"#gear/armor-vest-for-success\">Vest for Success<\/a>, take <a href=\"#quests/richie-s-rock-hard-roulette-challenge\">Richie&#x27;s Rock-Hard Roulette Challenge<\/a>.","s":[30]},{"h":"Bet on 12 and 14 once the jackpot bunny hints at a win.","s":[30]}],"get_h":["<a href=\"#forge/book-glam-gear-for-go-getters\">Glam Gear for Go-Getters<\/a> - <a href=\"#quests/madame-labouche-s-life-lesson\">Madame Labouche&#x27;s Life Lesson<\/a> reward","<a href=\"#gear/item-chronocrystal\">Chronocrystal<\/a> - <a href=\"#quests/one-last-request\">One Last Request<\/a> reward","<a href=\"#gear/item-lorelei-s-harp\">Lorelei&#x27;s Harp<\/a> - regained after <a href=\"#boss/booga\">Booga<\/a>","<a href=\"#gear/weapon-imp-knife\">Imp Knife<\/a> - Octagonia casino prize, not found elsewhere","<a href=\"#gear/armor-vest-for-success\">Vest for Success<\/a> - <a href=\"#quests/richie-s-rock-hard-roulette-challenge\">Richie&#x27;s Rock-Hard Roulette Challenge<\/a> reward"],"source":[{"t":"Reuniting with Jade / Act II / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-ii/reuniting-with-jade"}]},"a2-erik":{"steps":[{"h":"Sail through the Valor-Sauvage Channel.","s":[31]},{"h":"Stop at The Strand to register it for Zoom.","s":[31]},{"h":"At Insula Algarum, ride a <b>Dragon Rider<\/b> to the hidden chests, including an <a href=\"#gear/item-agate-of-evolution\">Agate of Evolution<\/a> on a small island.","s":[31]},{"h":"In Lonalulu, accept <a href=\"#quests/soothing-seaweed\">Soothing Seaweed<\/a>.","s":[31]},{"h":"Accept <a href=\"#quests/my-kingdom-for-some-kanaloamari\">My Kingdom for Some Kanaloamari<\/a>.","s":[31]},{"h":"Accept <a href=\"#quests/the-measure-of-a-man\">The Measure of a Man<\/a>.","s":[31]},{"h":"If <a href=\"#quests/my-kingdom-for-some-kanaloamari\">My Kingdom for Some Kanaloamari<\/a> or <a href=\"#quests/the-measure-of-a-man\">The Measure of a Man<\/a> is missing, learn <b>Flame Slash<\/b> and <b>Unbridled Blade<\/b>.","s":[31]},{"h":"Get the <a href=\"#gear/item-dulcet-dulse\">Dulcet Dulse<\/a> from the merman on the Insula Algarum bridge.","s":[31]},{"h":"Hand the <a href=\"#gear/item-dulcet-dulse\">Dulcet Dulse<\/a> in at Lonalulu for <a href=\"#gear/item-molten-globules\">Molten Globules<\/a>.","s":[31]},{"h":"Sail far north of Sniflheim to the Vortex of Light to trigger the <a href=\"#boss/alizarin\">Alizarin<\/a> fight.","s":[31]},{"h":"Against <a href=\"#boss/alizarin\">Alizarin<\/a> (about 4800 HP), have <a href=\"#party/jade\">Jade<\/a> use <b>Re-Vamp<\/b> twice then <a href=\"#party/jade\">Multithrust<\/a>.","s":[31]},{"h":"Have <a href=\"#party/hendrik\">Hendrik<\/a> use <b>Kabuff<\/b> and <b>Helm Splitter<\/b> in the same fight.","s":[31]},{"h":"Stay fully healed during Crimson Mist and counter his slowdown; <a href=\"#party/sylvando\">Sylvando<\/a> heals with <a href=\"#party/sylvando\">Hustle Dance<\/a> or casts <b>Oomphle<\/b> on the <a href=\"#party/hero\">Luminary<\/a>.","s":[31]},{"h":"In Sniflheim, see Queen Frysabel.","s":[31]},{"h":"Visit the priest&#x27;s back room.","s":[31]},{"h":"Fight the golden monsters in town, focusing the <a href=\"#boss/gyldenbritches\">Gyldenbritches<\/a>.","s":[31]},{"h":"Sail to the Viking Hideout.","s":[31]},{"h":"Clear the Gyldennauts with <b>Quadraslash<\/b>.","s":[31]},{"h":"Touch the Yggdrasil root to restore <a href=\"#party/erik\">Erik<\/a>.","s":[31]},{"h":"Rebuild <a href=\"#party/erik\">Erik<\/a> with <a href=\"#party/erik\">Cobra Strike<\/a>, <b>Victimiser<\/b>, dual-wielding and <a href=\"#party/erik\">Divide<\/a>.","s":[31]},{"h":"Open the chest east of the shelter for <a href=\"#forge/book-snowfield-styles\">Snowfield Styles<\/a>.","s":[31]},{"h":"Enter the Gyldenhal.","s":[31]},{"h":"In the Gyldenhal, take <a href=\"#forge/book-gilt-gear\">Gilt Gear<\/a> on Level 2.","s":[31]},{"h":"Avoid the slot machines that are Penny Pinchers in disguise.","s":[31]},{"h":"Fight <a href=\"#boss/gyldygga\">Gyldygga<\/a> (about 3600 HP).","s":[31]},{"h":"Use <b>Blunt<\/b> on her after she uses <b>Oomphle<\/b>.","s":[31]},{"h":"Keep <a href=\"#party/hendrik\">Hendrik<\/a> as backup healer in case gold traps your main one.","s":[31]},{"h":"Buy a <a href=\"#gear/weapon-paladin-s-lance\">Paladin&#x27;s Lance<\/a> for <a href=\"#party/jade\">Jade<\/a>.","s":[31]},{"h":"Find the diploma student upstairs in the weapon shop.","s":[31]},{"h":"Zoom back to L&#x27;Academie to complete the quest.","s":[31]}],"get_h":["<a href=\"#gear/item-agate-of-evolution\">Agate of Evolution<\/a> - Insula Algarum island chest, needs a mount","<a href=\"#forge/book-snowfield-styles\">Snowfield Styles<\/a> - Viking Hideout, east of the shelter","<a href=\"#forge/book-gilt-gear\">Gilt Gear<\/a> - Gyldenhal Level 2 chest","<a href=\"#gear/headwear-corsair-s-cap\">Corsair&#x27;s Cap<\/a> - from beating <a href=\"#boss/gyldygga\">Gyldygga<\/a>","<a href=\"#forge/book-gear-that-glitters\">Gear that Glitters<\/a> - <a href=\"#quests/a-delayed-diploma\">A Delayed Diploma<\/a> reward","<a href=\"#gear/weapon-deft-dagger\">Deft Dagger<\/a> - mini medal reward at L&#x27;Academie"],"source":[{"t":"Reuniting with Erik / Act II / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-ii/reuniting-with-erik"}]},"a2-twins":{"steps":[{"h":"Take the Vortex of Light near Zwaardsrust to Nautica.","s":[32]},{"h":"Accept <a href=\"#quests/marking-a-momentous-occasion\">Marking a Momentous Occasion<\/a> in Nautica.","s":[32]},{"h":"Accept <a href=\"#quests/justice-is-brined\">Justice is Brined<\/a> in Nautica.","s":[32]},{"h":"Pep up the <a href=\"#party/hero\">Luminary<\/a>, <a href=\"#party/hendrik\">Hendrik<\/a> and <a href=\"#party/sylvando\">Sylvando<\/a>.","s":[32]},{"h":"Use <b>Arise<\/b> on the <a href=\"#boss/knight-aberrant\">Knight Aberrant<\/a> in The Eerie Eyrie for a <a href=\"#gear/shield-metal-slime-shield\">Metal Slime Shield<\/a>.","s":[32]},{"h":"On Insula Incognita, finish a <b>Night Clubber<\/b> with <b>Buff-Buff<\/b> once its name turns orange.","s":[32]},{"h":"Claim a <a href=\"#gear/accessory-venus-tear\">Venus&#x27; Tear<\/a> in Lonalulu.","s":[32]},{"h":"Collect the <a href=\"#gear/item-kanono-cannon\">Kanono Cannon<\/a> from the cannon lady in the house north of Lonalulu&#x27;s item shop.","s":[32]},{"h":"In the northern seas, finish a <a href=\"#boss/tentacular\">Tentacular<\/a> with <b>Tempered Tantrum<\/b> for the <a href=\"#gear/item-kanaloamari\">Kanaloamari<\/a>.","s":[32]},{"h":"Trade the <a href=\"#gear/item-kanaloamari\">Kanaloamari<\/a> in Lonalulu for a <a href=\"#gear/weapon-pentarang\">Pentarang<\/a>.","s":[32]},{"h":"Open the chest in the Insula Occidentalis cabin for the <a href=\"#gear/item-sealicitor-s-statutes\">Sealicitor&#x27;s Statutes<\/a>.","s":[32]},{"h":"In Nautica, give the turtle the <a href=\"#gear/item-kanono-cannon\">Kanono Cannon<\/a>.","s":[32]},{"h":"Give the Courthouse mermaid the notes for <a href=\"#forge/book-secrets-of-the-sunken-spirit\">Secrets of the Sunken Spirit<\/a> and a <a href=\"#gear/accessory-sovereign-seal\">Sovereign Seal<\/a>.","s":[32]},{"h":"Accept <a href=\"#quests/a-ballad-of-bravery\">A Ballad of Bravery<\/a> at the Warrior&#x27;s Rest Inn.","s":[32]},{"h":"Bring back <a href=\"#gear/item-luter-s-opus\">Luter&#x27;s Opus<\/a> from the southwest Dundrasil hut.","s":[32]},{"h":"In The Snaerfelt, accept <a href=\"#quests/a-dish-served-cold\">A Dish Served Cold<\/a>.","s":[32]},{"h":"Fight <b>Killing Machine<\/b>s at the Frozen Fjord until a <b>Type G0<\/b> appears.","s":[32]},{"h":"Equip any paralysis protection.","s":[32]},{"h":"Rest at the camp.","s":[32]},{"h":"Save at the camp.","s":[32]},{"h":"Head past the Frozen Fjord toward Arboria.","s":[32]},{"h":"Fight the <a href=\"#boss/auroral-serpent\">Auroral Serpent<\/a> (about 4900 HP).","s":[32]},{"h":"Heal every round.","s":[32]},{"h":"Cure paralysis with <a href=\"#party/sylvando\">Sylvando<\/a>&#x27;s <b>Tingle<\/b>.","s":[32]},{"h":"Deal damage with <b>Sap<\/b>, <b>Oomphle<\/b>-boosted <b>Unbridled Blade<\/b>, and <a href=\"#party/jade\">Jade<\/a>&#x27;s double <b>Re-Vamp<\/b> into <a href=\"#party/jade\">Multithrust<\/a>; <a href=\"#party/hendrik\">Hendrik<\/a> casts <b>Kabuff<\/b>.","s":[32]},{"h":"Give the reborn <a href=\"#party/serena\">Serena<\/a> <b>Enchanting Echo<\/b> first.","s":[32]},{"h":"Give her <b>Antimagic<\/b> next to open <a href=\"#party/serena\">Grace of the Goddess<\/a>.","s":[32]},{"h":"After getting the <a href=\"#gear/item-calamus-flute\">Calamus Flute<\/a>, accept <a href=\"#quests/a-long-lost-literary-love\">A Long-Lost Literary Love<\/a> in Arboria.","s":[32]},{"h":"Fly to each Whale Way Station for loot.","s":[32]}],"get_h":["<a href=\"#forge/book-secrets-of-the-sunken-spirit\">Secrets of the Sunken Spirit<\/a> - <a href=\"#quests/marking-a-momentous-occasion\">Marking a Momentous Occasion<\/a> reward","<a href=\"#forge/book-fine-fashions-for-philosophers\">Fine Fashions for Philosophers<\/a> - <a href=\"#quests/a-ballad-of-bravery\">A Ballad of Bravery<\/a> reward","<a href=\"#gear/armor-metal-slime-armor\">Metal Slime Armour<\/a> - <a href=\"#quests/a-dish-served-cold\">A Dish Served Cold<\/a> reward","<a href=\"#forge/book-an-album-of-imperial-attire\">An Album of Imperial Attire<\/a> - Sniflheim Whale Way Station, southwest chest","<a href=\"#forge/book-an-earring-for-every-element\">An Earring for Every Element<\/a> - Champs Sauvage Whale Way Station, north chest","<a href=\"#forge/book-even-more-dragony-designs\">Even More Dragony Designs<\/a> - Hotto Steppe northern Whale Way Station, behind the locked door"],"source":[{"t":"Reuniting with the Twins / Act II / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-ii/reuniting-with-the-twins"}]},"a2-sword":{"steps":[{"h":"At Havens Above, take the <a href=\"#gear/item-guiding-light\">Guiding Light<\/a> in the Temple of Dawn.","s":[33]},{"h":"Fly to The Battleground.","s":[33]},{"h":"Use the <a href=\"#gear/item-guiding-light\">Guiding Light<\/a> on the object ahead.","s":[33]},{"h":"Kill each <b>Pandora&#x27;s Box<\/b> chest quickly with your strongest attacks before it casts <b>Kathwack<\/b>; each drops a <a href=\"#gear/item-seed-of-skill\">Seed of Skill<\/a>.","s":[33]},{"h":"Mount a <b>Dragooner<\/b> in the central shaft to reach the caves that need flight.","s":[33]},{"h":"At the camp near the bottom of the shaft, forge an <a href=\"#gear/shield-ogre-shield\">Ogre Shield<\/a> for <a href=\"#party/hendrik\">Hendrik<\/a> and <a href=\"#gear/accessory-titan-belt\">Titan Belt<\/a>s for physical attackers.","s":[33]},{"h":"Open the eastern B9 chest for <a href=\"#forge/book-sacred-styles-for-saintly-ladies\">Sacred Styles for Saintly Ladies<\/a>.","s":[33]},{"h":"On B6, fly to the western chest for <a href=\"#forge/book-brace-yourself\">Brace Yourself<\/a>.","s":[33]},{"h":"Follow the long north path to the Overlooked Cavern.","s":[33]},{"h":"Take the <a href=\"#gear/item-orichalcum\">Orichalcum<\/a>.","s":[33]},{"h":"In Gondolia, haggle between the brothers to buy <a href=\"#gear/armor-hendrik-s-armor\">Hendrik&#x27;s Armour<\/a> for 10000G.","s":[33]},{"h":"Buy a <a href=\"#gear/weapon-fizzle-foil\">Fizzle Foil<\/a>.","s":[33]},{"h":"At the Grotta della Fonte camp, forge the <a href=\"#gear/headwear-goddess-s-tiara\">Goddess&#x27;s Tiara<\/a> and <a href=\"#gear/armor-saintess-dress\">Saintess Dress<\/a> for <a href=\"#party/serena\">Serena<\/a>, plus <a href=\"#gear/accessory-mighty-armlet\">Mighty Armlet<\/a>s and <a href=\"#gear/accessory-brainy-bracer\">Brainy Bracer<\/a>s.","s":[33]},{"h":"Clear <a href=\"#quests/worth-its-salt\">Worth Its Salt<\/a>, <a href=\"#quests/a-right-riddle\">A Right Riddle<\/a> (equip the <a href=\"#gear/weapon-fizzle-foil\">Fizzle Foil<\/a>), <a href=\"#quests/the-search-for-the-sage-s-stone\">The Search for the Sage&#x27;s Stone<\/a> and <a href=\"#quests/a-rose-arose-where-no-rose-grows\">A Rose Arose Where No Rose Grows<\/a>.","s":[33]},{"h":"After the Celestial Sands event, talk to the Sultan in the Gallopolis throne room twice for the <a href=\"#gear/item-forging-hammer\">Forging Hammer<\/a>.","s":[33]},{"h":"At the Hotto Steppe camp, forge a <a href=\"#gear/weapon-metal-gooreatsword\">Metal Gooreatsword<\/a> for the <a href=\"#party/hero\">Luminary<\/a>.","s":[33]},{"h":"When <a href=\"#boss/tatsunaga\">Tatsunaga<\/a> attacks Hotto, have <a href=\"#party/hendrik\">Hendrik<\/a> cast <b>Kabuff<\/b>.","s":[33]},{"h":"Attack with <b>Unbridled Blade<\/b> and <a href=\"#party/jade\">Multithrust<\/a>.","s":[33]},{"h":"Watch for <a href=\"#boss/tatsunaga\">Tatsunaga<\/a>&#x27;s desperate attacks, which can top 200.","s":[33]},{"h":"In Mount Huji, fight <a href=\"#boss/tatsunaga\">Tatsunaga<\/a> (about 2400 HP).","s":[33]},{"h":"Keep <b>Kabuff<\/b> up.","s":[33]},{"h":"Use double <b>Re-Vamp<\/b> on <a href=\"#party/jade\">Jade<\/a>.","s":[33]},{"h":"Cast <b>Oomphle<\/b> on the <a href=\"#party/hero\">Luminary<\/a>.","s":[33]},{"h":"Get the <a href=\"#gear/item-crucible-key\">Crucible Key<\/a> from Miko&#x27;s maid.","s":[33]},{"h":"Unlock the far north door of Mount Huji.","s":[33]},{"h":"Present the <a href=\"#gear/item-guiding-light\">Guiding Light<\/a>.","s":[33]}],"get_h":["<a href=\"#forge/book-an-encyclopaedia-of-expert-equipment\">An Encyclopaedia of Expert Equipment<\/a> - The Battleground B3, first north cave","<a href=\"#forge/book-sacred-styles-for-saintly-ladies\">Sacred Styles for Saintly Ladies<\/a> - The Battleground B9, east chest","<a href=\"#forge/book-brace-yourself\">Brace Yourself<\/a> - The Battleground B6, needs a <b>Dragooner<\/b>","<a href=\"#forge/book-making-the-most-of-mythril\">Making the Most of Mythril<\/a> - <a href=\"#quests/the-search-for-the-sage-s-stone\">The Search for the Sage&#x27;s Stone<\/a> reward","<a href=\"#forge/book-things-to-do-with-metal-goo\">Things to Do with Metal Goo<\/a> - <a href=\"#quests/a-long-lost-literary-love\">A Long-Lost Literary Love<\/a> reward","<a href=\"#gear/armor-hendrik-s-armor\">Hendrik&#x27;s Armour<\/a> - Gondolia merchant, 10000G"],"source":[{"t":"Forging the Sword of Legend / Act II / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-ii/forging-the-sword-of-legend"}]},"a2-fortress":{"steps":[{"h":"Heal fully at an inn or camp.","s":[34]},{"h":"Use the <a href=\"#gear/item-calamus-flute\">Calamus Flute<\/a> to fly to the Fortress of Fear.","s":[34]},{"h":"Fight <a href=\"#boss/indignus\">Indignus<\/a> (about 3500 HP).","s":[34]},{"h":"Cast <b>Sap<\/b> on him.","s":[34]},{"h":"Cure Gigathrow paralysis with <b>Tingle<\/b> at once.","s":[34]},{"h":"Keep HP above half.","s":[34]},{"h":"Since he strips buffs, keep up steady damage with <a href=\"#party/jade\">Jade<\/a>&#x27;s <a href=\"#party/jade\">Multithrust<\/a> or <b>Multifeet<\/b> and an <b>Oomphle<\/b>d <b>Unbridled Blade<\/b> rather than rebuffing.","s":[34]},{"h":"Save at the Goddess Statue in the corner.","s":[34]},{"h":"Beat the <b>Dark Dullahan<\/b>s inside the door.","s":[34]},{"h":"Open the Level 1 west chest for <a href=\"#forge/book-pride-of-the-valkyries\">Pride of the Valkyries<\/a>.","s":[34]},{"h":"Forge <a href=\"#forge/book-pride-of-the-valkyries\">Pride of the Valkyries<\/a> at a camp for <a href=\"#party/jade\">Jade<\/a>.","s":[34]},{"h":"Take <a href=\"#forge/book-general-directives\">General Directives<\/a> from the Level 3 west chest.","s":[34]},{"h":"Open the shortcut.","s":[34]},{"h":"Forge <a href=\"#party/hendrik\">Hendrik<\/a>&#x27;s gear.","s":[34]},{"h":"On the Level 3 exterior, search behind the <b>Jerkules<\/b> for <a href=\"#forge/book-in-fine-fettle-with-liquid-metal\">In Fine Fettle with Liquid Metal<\/a>.","s":[34]},{"h":"After breaking the central crystals, forge the <a href=\"#gear/weapon-liquid-metal-gooreatsword\">Liquid Metal Gooreatsword<\/a>, <a href=\"#gear/weapon-liquid-metal-spear\">Liquid Metal Spear<\/a> and <a href=\"#gear/armor-liquid-metal-armor\">Liquid Metal Armour<\/a> for the <a href=\"#party/hero\">Luminary<\/a>.","s":[34]},{"h":"Hit the Level 4 switches.","s":[34]},{"h":"Open the north door on Level 1 for the <a href=\"#gear/accessory-meteorite-bracer\">Meteorite Bracer<\/a>.","s":[34]},{"h":"Give the <a href=\"#gear/accessory-meteorite-bracer\">Meteorite Bracer<\/a> to your healer.","s":[34]},{"h":"Save at the outside Goddess Statue.","s":[34]},{"h":"Grab the <a href=\"#gear/item-sage-s-elixir\">Sage&#x27;s Elixir<\/a> chest past the raised platforms.","s":[34]},{"h":"Cross the bridge.","s":[34]},{"h":"Fight <a href=\"#boss/jasper-unbound\">Jasper Unbound<\/a> (about 3600 HP).","s":[34]},{"h":"Have <a href=\"#party/hendrik\">Hendrik<\/a> cast <b>Kabuff<\/b> so Jasper wastes turns removing it.","s":[34]},{"h":"Ignore Jasper&#x27;s summons.","s":[34]},{"h":"Attack Jasper with <a href=\"#party/hero\">Sword Dance<\/a> or <b>Unbridled Blade<\/b> plus <b>Multifeet<\/b>.","s":[34]},{"h":"Keep one healer on duty with HP above half.","s":[34]},{"h":"Stock MP items and <a href=\"#gear/item-yggdrasil-leaf\">Yggdrasil Leaf<\/a>s.","s":[34]},{"h":"Fight <a href=\"#boss/mordegon-lord-of-shadows\">Mordegon, Lord of Shadows<\/a> (about 5500 HP).","s":[34]},{"h":"Kill the <a href=\"#boss/shadow-of-shadows\">Shadow of Shadows<\/a> before it casts <b>Kabuff<\/b>.","s":[34]},{"h":"Against <a href=\"#boss/mordegon-lord-of-shadows\">Mordragon<\/a>, kill <a href=\"#boss/mordegon-lord-of-shadows\">Mordragon&#x27;s tail<\/a> first so it cannot revive him with <b>Kazing<\/b>.","s":[34]},{"h":"Use <b>Magic Barrier<\/b>.","s":[34]},{"h":"Swap tired party members in.","s":[34]}],"get_h":["<a href=\"#forge/book-pride-of-the-valkyries\">Pride of the Valkyries<\/a> - Level 1 west chest, best Act II armour for <a href=\"#party/jade\">Jade<\/a>","<a href=\"#forge/book-general-directives\">General Directives<\/a> - Level 3 west chest, best Act II gear for <a href=\"#party/hendrik\">Hendrik<\/a>","<a href=\"#forge/book-in-fine-fettle-with-liquid-metal\">In Fine Fettle with Liquid Metal<\/a> - Level 3 exterior, behind the <b>Jerkules<\/b>","<a href=\"#gear/accessory-meteorite-bracer\">Meteorite Bracer<\/a> - Level 1, behind the locked north door","<a href=\"#gear/armor-liquid-metal-jacket\">Liquid Metal Jacket<\/a> - Level 1 west, under the stairs"],"source":[{"t":"The Fortress of Fear / Act II / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-ii/the-fortress-of-fear"}]},"a3-lost-time":{"steps":[{"h":"Try to leave Arboria after the party scene.","s":[35]},{"h":"Zoom to the Dundrasil camp when you are ready to push the story on.","s":[35]},{"h":"Go through the northern pass toward Octagonia.","s":[35]},{"h":"Go south to the Mysterious Ruins.","s":[35]},{"h":"Take the <a href=\"#gear/item-wheel-of-time\">Wheel of Time<\/a> on their west side.","s":[35]},{"h":"Fly <b>Cetacea<\/b> to the tower north of Yggdrasil.","s":[35]},{"h":"Open the chest behind the tower to the northwest for <a href=\"#forge/book-good-godly-gear\">Good Godly Gear<\/a>.","s":[35]},{"h":"Open the tower door with the <a href=\"#gear/item-wheel-of-time\">Wheel of Time<\/a>.","s":[35]},{"h":"Collect <a href=\"#forge/book-a-hero-s-book-of-basic-weapons\">A Hero&#x27;s Book of Basic Weapons<\/a> on the northern cog route to evolve your <a href=\"#gear/weapon-poker\">Poker<\/a>, <a href=\"#gear/weapon-stardust-sword\">Stardust Sword<\/a> or <a href=\"#gear/weapon-bad-axe\">Bad axe<\/a>.","s":[35]},{"h":"Talk to every companion at the Altar of Ages.","s":[35]},{"h":"Agree through <a href=\"#party/erik\">Erik<\/a>.","s":[35]},{"h":"Shatter the Time Sphere.","s":[35]},{"h":"Re-equip the party with the gear they wore at the end of Act II; their levels come back later in the story.","s":[35]},{"h":"Walk straight through the First Forest to Yggdrasil without grinding, using the Orbs at the altar.","s":[35]},{"h":"Against <a href=\"#boss/jasper\">Jasper<\/a>, spam <a href=\"#party/hero\">Sword Dance<\/a> with the <a href=\"#party/hero\">Luminary<\/a> (550+ per use against roughly 2055 HP) while <a href=\"#party/sylvando\">Sylvando<\/a> heals.","s":[35]},{"h":"If <a href=\"#boss/jasper\">Jasper<\/a> cloaks himself with the Orb, hit him with the <a href=\"#party/hero\">Luminary<\/a> first to break it before the others attack.","s":[35]},{"h":"In Heliodor Castle, grab the <a href=\"#gear/item-seed-of-defence\">Seed of Defence<\/a> from the kitchen side room.","s":[35]},{"h":"Grab the <a href=\"#gear/accessory-mighty-armlet\">Mighty armlet<\/a> from Hendrik&#x27;s quarters.","s":[35]},{"h":"Save with the Priest.","s":[35]},{"h":"Against <a href=\"#boss/mordegon\">Mordegon<\/a> (2500 HP), ignore the staves unless you are using group attacks.","s":[35]},{"h":"Use <b>Boom<\/b> with <a href=\"#party/veronica\">Veronica<\/a> when the staves are out.","s":[35]},{"h":"Have <a href=\"#party/sylvando\">Sylvando<\/a> or <a href=\"#party/veronica\">Veronica<\/a> cast <b>Oomph<\/b> on the <a href=\"#party/hero\">Luminary<\/a>.","s":[35]},{"h":"Attack with <a href=\"#party/hero\">Sword Dance<\/a> or <b>Unbridled Blade<\/b>.","s":[35]},{"h":"If Purple Mist is active, stop all healing spells until it fades, because it turns healing and buffs against you.","s":[35]},{"h":"Travel to the Emerald Coast.","s":[35]},{"h":"Take the <a href=\"#gear/item-calamus-flute\">Calamus Flute<\/a>.","s":[35]},{"h":"Fly to the floating island in the northeast.","s":[35]},{"h":"Speak to the Elder at the Place of Legends in Havens Above.","s":[35]},{"h":"Open the nearby chest for the <a href=\"#gear/item-ultimate-key\">Ultimate key<\/a>.","s":[35]},{"h":"Take the Guiding Light at the Temple of Dawn to restore levels and Zoom points.","s":[35]},{"h":"Plan skills toward <a href=\"#party/hero\">Gigagash<\/a>, <a href=\"#party/veronica\">Kaboomle<\/a>, <a href=\"#party/serena\">Grace of the Goddess<\/a> and <a href=\"#party/rab\">Clear Your Mind<\/a>.","s":[35]},{"h":"Accept Quest 48 <a href=\"#quests/wisdom-of-the-warrior-king\">Wisdom of the Warrior King<\/a> on the southwest island and Quest 49 from the Watcher by the northeast Item shop.","s":[35]}],"get_h":["<a href=\"#forge/book-good-godly-gear\">Good Godly Gear<\/a> - Lost Land, chest behind the Tower of Lost Time","<a href=\"#forge/book-a-hero-s-book-of-basic-weapons\">A Hero&#x27;s Book of Basic Weapons<\/a> - Tower of Lost Time, before the last cog","<a href=\"#gear/item-calamus-flute\">Calamus Flute<\/a> - from Veronica on the Emerald Coast","<a href=\"#gear/item-ultimate-key\">Ultimate key<\/a> - Havens Above, Place of Legends chest"],"source":[{"t":"In Search of Lost Time / Act III / Post Game / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-iii-post-game/in-search-of-lost-time"}]},"a3-tour":{"steps":[{"h":"Speak to Gemma at your home in Cobblestone to begin the rebuilding quest that runs through all of Act III.","s":[36]},{"h":"Fight the Malicious <a href=\"#boss/hades-condor\">Hades condor<\/a> in Cobblestone Tor (about 4500 HP).","s":[36]},{"h":"Have <a href=\"#party/hendrik\">Hendrik<\/a> cast <b>Magic Barrier<\/b> against its 200+ HP <b>Kasizzle<\/b>.","s":[36]},{"h":"Heal with <a href=\"#gear/item-sage-s-stone\">Sage&#x27;s stone<\/a>.","s":[36]},{"h":"Attack the condor with <b>Sword Dance<\/b> and a <b>Re-Vamp<\/b>ed <a href=\"#party/jade\">Jade<\/a> using <b>Multifeet<\/b>.","s":[36]},{"h":"Climb the Tor summit to accept Quest 50 <a href=\"#quests/mister-vista\">Mister Vista<\/a>.","s":[36]},{"h":"Talk to the King of Heliodor for the <a href=\"#gear/headwear-golden-tiara\">Golden tiara<\/a>.","s":[36]},{"h":"Take Tome 1 of Quest 48 from Jasper&#x27;s room.","s":[36]},{"h":"Open the dungeon cells for <a href=\"#forge/book-king-of-the-swindlers\">King of the Swindlers<\/a>.","s":[36]},{"h":"Liberate Gondolia.","s":[36]},{"h":"Open its Ultimate Key door for 50000G.","s":[36]},{"h":"Haggle the merchant brothers down to 20000G for Jade&#x27;s <a href=\"#gear/armor-divine-bustier\">Divine bustier<\/a>.","s":[36]},{"h":"Ride a Malicious <b>Dragooner<\/b> around Insula Centralis for <a href=\"#gear/item-orichalcum\">Orichalcum<\/a> and three <a href=\"#gear/item-agate-of-evolution\">Agate of Evolution<\/a>.","s":[36]},{"h":"Finish <a href=\"#quests/mister-vista\">Mister Vista<\/a> in Cobblestone Tor for a <a href=\"#gear/weapon-fantastick\">Fantastick<\/a>.","s":[36]},{"h":"At the First Forest Whale Way Station, take <a href=\"#forge/book-upper-class-accessories\">Upper-Class Accessories<\/a> and the <a href=\"#gear/item-pepper-tree-branch\">Pepper tree branch<\/a>.","s":[36]},{"h":"Hand the branch to Faris to finish <a href=\"#quests/perfectly-pepped-paladins\">Perfectly Pepped Paladins<\/a> for four <a href=\"#gear/item-pep-pip\">Pep pip<\/a>s.","s":[36]},{"h":"Trade Mini Medals at L&#x27;Academie for the <a href=\"#gear/accessory-circle-of-serendipity\">Circle of serendipity<\/a>.","s":[36]},{"h":"Forge the <a href=\"#gear/weapon-straight-poker\">Straight poker<\/a> at a camp.","s":[36]},{"h":"Rework the <a href=\"#gear/armor-metal-king-armor\">Metal king armour<\/a> and <a href=\"#gear/weapon-fantastick\">Fantastick<\/a> at a camp.","s":[36]},{"h":"In the Kingsbarrow, Pep Up <a href=\"#party/sylvando\">Sylvando<\/a> and <a href=\"#party/hendrik\">Hendrik<\/a> on the way down.","s":[36]},{"h":"Bench them.","s":[36]},{"h":"Wear <a href=\"#boss/tweedledoom\">Tweedledoom<\/a> (3000 HP, Seismic Shock) to orange HP first.","s":[36]},{"h":"Swap <a href=\"#party/sylvando\">Sylvando<\/a> and <a href=\"#party/hendrik\">Hendrik<\/a> in to finish each Tweedle with Executioner; if <a href=\"#party/hendrik\">Hendrik<\/a> is no longer Pepped for the second one, throw him a <a href=\"#gear/item-pep-pip\">Pep pip<\/a>.","s":[36]},{"h":"From here on, open every big fight with <a href=\"#party/hendrik\">Hendrik<\/a> casting <b>Immense Defence<\/b>.","s":[36]},{"h":"Have <a href=\"#party/hendrik\">Hendrik<\/a> follow with <a href=\"#party/hendrik\">Forbearance<\/a>.","s":[36]},{"h":"Let <a href=\"#party/sylvando\">Sylvando<\/a> hand turns to <a href=\"#party/jade\">Jade<\/a> with <b>Ladies First<\/b>.","s":[36]},{"h":"Fight the Malicious <a href=\"#boss/gloomnivore\">Gloomnivore<\/a> under Dundrasil (about 5200 HP).","s":[36]},{"h":"Land <b>Sap<\/b> and Blunt on him.","s":[36]},{"h":"Attack with <a href=\"#party/hero\">Sword Dance<\/a> and <b>Multifeet<\/b>.","s":[36]},{"h":"Against the Malicious <a href=\"#boss/merking\">Merking<\/a> at The Strand, focus the Merking.","s":[36]},{"h":"Hit the <a href=\"#boss/mermaniac\">Mermaniac<\/a>s only with group attacks like <a href=\"#party/veronica\">Kaboomle<\/a>, <a href=\"#party/sylvando\">Gold Rush<\/a> and <a href=\"#party/jade\">Pink Tornado<\/a>.","s":[36]},{"h":"Bring <a href=\"#party/serena\">Serena<\/a> and <a href=\"#party/sylvando\">Sylvando<\/a> to the <a href=\"#boss/merking\">Merking<\/a> fight.","s":[36]},{"h":"Hunt a <b>Harmachis<\/b> at the Southern Hotto Steppe station with the <a href=\"#gear/accessory-circle-of-serendipity\">Circle of serendipity<\/a> to finish <a href=\"#quests/might-is-right\">Might Is Right!<\/a> for the <a href=\"#gear/weapon-apollo-s-axe\">Apollo&#x27;s axe<\/a>.","s":[36]},{"h":"Fight <a href=\"#boss/bathysfear\">Bathysfear<\/a> (about 5600 HP).","s":[36]},{"h":"Keep HP above 300.","s":[36]},{"h":"Tank Ready Blade with <a href=\"#party/hendrik\">Forbearance<\/a>.","s":[36]},{"h":"Land <b>Sap<\/b> before the <a href=\"#party/hero\">Luminary<\/a> starts attacking.","s":[36]},{"h":"In the Caverns Under Octagonia, beat the MMA fighters with <b>Kaboomle<\/b> fed by <a href=\"#party/sylvando\">Sylvando<\/a>.","s":[36]},{"h":"Face the Malicious <a href=\"#boss/arachtagon\">Arachtagon<\/a> (about 5600 HP) with a twice <b>Re-Vamp<\/b>ed <a href=\"#party/jade\">Jade<\/a> and <b>Snap, Crackle, Poof<\/b>.","s":[36]},{"h":"Against the Malicious <a href=\"#boss/grey-gordon\">Grey gordon<\/a> (about 5400 HP), kill Gordon first.","s":[36]},{"h":"Clear Gordon&#x27;s summons with <a href=\"#party/jade\">Pink Tornado<\/a>, <a href=\"#party/veronica\">Kaboomle<\/a> and <a href=\"#party/hero\">Gigagash<\/a> or <b>Quadraslash<\/b>.","s":[36]},{"h":"Against the Malicious <a href=\"#boss/j-rmun\">Jörmun<\/a> (about 2800 HP), land the killing blow with a <a href=\"#party/hero\">Zap<\/a>-family spell from the <a href=\"#party/hero\">Luminary<\/a>.","s":[36]},{"h":"Bring <a href=\"#party/erik\">Erik<\/a> to the <a href=\"#boss/j-rmun\">Jörmun<\/a> fight for <b>Cock-a-doodle-doo<\/b> against <b>Kasnooze<\/b>.","s":[36]},{"h":"Against the Malicious Arboreal Serpent (about 7600 HP), equip Paralysis protection.","s":[36]},{"h":"Bring <a href=\"#party/sylvando\">Sylvando<\/a> to the Arboreal Serpent fight for <b>Tingle<\/b>, <b>Oomphle<\/b> and <a href=\"#party/sylvando\">Ladies First<\/a>.","s":[36]},{"h":"Touch the last Seedlings at the Laguna di Gondolia and Zwaardsrust stations.","s":[36]},{"h":"Take the <a href=\"#gear/item-wheel-of-time\">Wheel of Time<\/a> from the Elder.","s":[36]},{"h":"Climb the Tower of Lost Time again.","s":[36]}],"get_h":["<a href=\"#gear/armor-divine-bustier\">Divine bustier<\/a> - Gondolia merchant brothers, haggle to 20000G","<a href=\"#gear/armor-pirate-king-s-coat\">Pirate king&#x27;s coat<\/a> - rebuilt Cobblestone shop, completes Erik&#x27;s set","<a href=\"#forge/book-glammer-gear-for-goer-getterers\">Glammer Gear for Goer-Getterers<\/a> - L&#x27;Academie Mini Medal reward","<a href=\"#forge/book-the-way-of-the-war-goddess\">The Way of the War Goddess<\/a> - Battleground B9, after the <b>Crystalotl<\/b>","<a href=\"#gear/item-harmonicrystal\">Harmonicrystal<\/a> - from the <b>Crystalotl<\/b>, completes Quest 49","<a href=\"#gear/accessory-gemma-s-eternal-charm\">Gemma&#x27;s eternal charm<\/a> - Gemma, once Cobblestone is rebuilt"],"source":[{"t":"A Tour of Erdrea / Act III / Post Game / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-iii-post-game/a-tour-of-erdrea"}]},"a3-old-friend":{"steps":[{"h":"Stack dark resistance on <a href=\"#party/hendrik\">Hendrik<\/a> before starting, for example the <a href=\"#gear/armor-field-marshal-s-finery\">Field marshal&#x27;s finery<\/a> (40% at +3) and the <a href=\"#gear/shield-ruinous-shield\">Ruinous shield<\/a> (50% at +3).","s":[37]},{"h":"Talk to the guard with the pink speech bubble in the main hall of Heliodor Castle.","s":[37]},{"h":"Touch the Yggdrasil root in the courtyard.","s":[37]},{"h":"Follow the shadow to the dining hall&#x27;s side room.","s":[37]},{"h":"Interact at the shelf.","s":[37]},{"h":"Go to Jasper&#x27;s old room.","s":[37]},{"h":"Interact with the shadow.","s":[37]},{"h":"Read the journal on the table.","s":[37]},{"h":"Follow the shadow from the main hall past the throne room and upstairs to the balcony to trigger the duel.","s":[37]},{"h":"Attack with your strongest single-target skill: <a href=\"#party/hendrik\">Parallax<\/a> with an axe, <b>Unbridled Blade<\/b> with a greatsword, or <a href=\"#party/hendrik\">Gyrfalcon Slash<\/a> with a sword.","s":[37]},{"h":"Heal with <a href=\"#party/hero\">Moreheal<\/a> only when needed.","s":[37]},{"h":"Against <a href=\"#boss/jasper-unbound\">Jasper Unbound<\/a>, skip buffs unless you need them, since his disruptive wave strips them.","s":[37]},{"h":"Keep attacking in the third phase, when the darkness damages Jasper on its own and most of his attacks miss.","s":[37]}],"get_h":["<a href=\"#gear/armor-twin-eagle-armor\">Twin eagle armour<\/a> - reward for the duel, needed for the costume trophy"],"source":[{"t":"An Old Friend / Act III / Post Game / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-iii-post-game/an-old-friend"}]},"a3-drustan":{"steps":[{"h":"Go through the glyph door in the ruins west of the Warrior&#x27;s Rest Inn.","s":[38]},{"h":"Take the portal into the Realm Between Worlds.","s":[38]},{"h":"In Drustan&#x27;s Labyrinth, loot the <a href=\"#gear/armor-sacred-armor\">Sacred armour<\/a> behind the cabin and the <a href=\"#gear/item-serpent-s-soul\">Serpent&#x27;s soul<\/a>, using a <b>Visor kaiser<\/b> mount to break the ice.","s":[38]},{"h":"At Trial Isle, forge new gear.","s":[38]},{"h":"Zoom to Havens Above.","s":[38]},{"h":"Accept Quest 60 <a href=\"#quests/lost-lovers\">Lost Lovers<\/a> from the Watcher.","s":[38]},{"h":"In the Cruel Crypt, drop through the southeast hole for <a href=\"#forge/book-kings-of-the-rings\">Kings of the Rings<\/a>.","s":[38]},{"h":"Take <a href=\"#gear/item-erdwin-s-bracelet\">Erdwin&#x27;s bracelet<\/a> from the slot machine room.","s":[38]},{"h":"In the Eerie Valley, collect the <a href=\"#gear/item-lumen-essence\">Lumen essence<\/a>, <a href=\"#forge/book-a-hero-s-book-of-better-weapons\">A Hero&#x27;s Book of Better Weapons<\/a> and <a href=\"#gear/headwear-drustan-s-helm\">Drustan&#x27;s helm<\/a>.","s":[38]},{"h":"Put the helm on <a href=\"#party/hendrik\">Hendrik<\/a>.","s":[38]},{"h":"Fight <a href=\"#boss/blind-hatred\">Blind hatred<\/a> (4200 HP, 25 turns).","s":[38]},{"h":"Tank with <a href=\"#party/hendrik\">Hendrik<\/a>&#x27;s <b>Immense Defence<\/b> and <a href=\"#party/hendrik\">Forbearance<\/a>.","s":[38]},{"h":"Kill each 900 HP Shadow fast.","s":[38]},{"h":"Deal damage with <b>Re-Vamp<\/b>ed <b>Multifeet<\/b> boosted by <a href=\"#party/sylvando\">Sylvando<\/a>&#x27;s <a href=\"#party/sylvando\">Ladies First<\/a>, or <a href=\"#party/erik\">Erik<\/a>&#x27;s poison-boosted <a href=\"#party/erik\">Divide<\/a> attacks under <b>Oomphle<\/b>.","s":[38]},{"h":"Pick the Super Powerful Weapon wish first to get <a href=\"#forge/book-supreme-secrets-of-the-sword-of-light\">Supreme Secrets of the Sword of Light<\/a>.","s":[38]},{"h":"Turn in <a href=\"#quests/lost-lovers\">Lost Lovers<\/a>.","s":[38]},{"h":"In Hotto, accept <a href=\"#quests/the-legendary-treasure-of-legend\">The Legendary Treasure of Legend<\/a> at the Inn.","s":[38]},{"h":"Sell <a href=\"#gear/item-orichalcum\">Orichalcum<\/a> to the man outside the western Item shop.","s":[38]},{"h":"Collect the <a href=\"#gear/item-hotto-stuff\">Hotto stuff<\/a> past Mount Huji&#x27;s Secret Entrance.","s":[38]},{"h":"Give Miko the <a href=\"#gear/item-lumen-essence\">Lumen essence<\/a>.","s":[38]},{"h":"Buy the <a href=\"#gear/weapon-sword-of-kings\">Sword of Kings<\/a>.","s":[38]},{"h":"Get the <a href=\"#gear/item-crucible-key\">Crucible key<\/a>.","s":[38]},{"h":"Win the Easy Gold Cup at the Gallopolis Racetrack for the <a href=\"#gear/item-forging-hammer\">Forging hammer<\/a>, aiming for a lap time of 22-23 seconds.","s":[38]},{"h":"Trade two <a href=\"#gear/item-serpent-s-soul\">Serpent&#x27;s soul<\/a>s to Krystalinda for <a href=\"#gear/item-crimsonite\">Crimsonite<\/a>s.","s":[38]},{"h":"Forge a <a href=\"#gear/weapon-sword-of-light\">Sword of Light<\/a> at the Crucible.","s":[38]},{"h":"Forge the <a href=\"#gear/weapon-supreme-sword-of-light\">Supreme Sword of Light<\/a> on Trial Isle.","s":[38]},{"h":"Dual-wield the <a href=\"#gear/weapon-super-sword-of-light\">Super Sword of Light<\/a> and <a href=\"#gear/weapon-supreme-sword-of-light\">Supreme Sword of Light<\/a> +3 on the <a href=\"#party/hero\">Luminary<\/a> if he knows <a href=\"#party/hero\">Gigagash<\/a> and <a href=\"#party/hero\">Sword Dance<\/a>.","s":[38]},{"h":"Loot <a href=\"#gear/headwear-serenica-s-circlet\">Serenica&#x27;s circlet<\/a> in the Fierce Forest.","s":[38]},{"h":"Loot <a href=\"#gear/shield-drustan-s-shield\">Drustan&#x27;s shield<\/a> and <a href=\"#forge/book-eternal-elegance\">Eternal Elegance<\/a> in Hoarder&#x27;s Keep, using <b>Peep<\/b> to spot the Token Takers.","s":[38]},{"h":"Fight <a href=\"#boss/unfathomable-anger\">Unfathomable anger<\/a> (7500 HP, 30 turns).","s":[38]},{"h":"Land <b>Sap<\/b>.","s":[38]},{"h":"Tank with <a href=\"#party/hendrik\">Hendrik<\/a>.","s":[38]},{"h":"Have a double <b>Re-Vamp<\/b>ed <a href=\"#party/jade\">Jade<\/a> use <b>Multifeet<\/b> for 1000+ damage.","s":[38]},{"h":"Pick the wedding wish.","s":[38]},{"h":"Rework <a href=\"#gear/shield-drustan-s-shield\">Drustan&#x27;s shield<\/a> to +3.","s":[38]},{"h":"Finish the L&#x27;Academie album for <a href=\"#gear/shield-erdwin-s-shield\">Erdwin&#x27;s shield<\/a> and <a href=\"#forge/book-making-things-with-metal-kings\">Making Things with Metal Kings<\/a>.","s":[38]},{"h":"In the Citadel of Spite, take <a href=\"#gear/weapon-drustan-s-sword\">Drustan&#x27;s Sword<\/a>.","s":[38]},{"h":"Switch <a href=\"#party/hendrik\">Hendrik<\/a> to sword and shield.","s":[38]},{"h":"Open the red door for <a href=\"#gear/armor-drustan-s-armor\">Drustan&#x27;s armour<\/a>, <a href=\"#gear/armor-erdwin-s-tunic\">Erdwin&#x27;s tunic<\/a> and <a href=\"#gear/armor-serenica-s-surplice\">Serenica&#x27;s surplice<\/a>.","s":[38]},{"h":"Fight <a href=\"#boss/sheer-decadence\">Sheer Decadence<\/a> (4800 HP) and <a href=\"#boss/all-consuming-greed\">All-consuming greed<\/a> (about 2600 HP, 40 turns).","s":[38]},{"h":"Open with <a href=\"#party/veronica\">Veronica<\/a>&#x27;s <b>Magic Burst<\/b> for 1500+.","s":[38]},{"h":"Bench <a href=\"#party/veronica\">Veronica<\/a>.","s":[38]},{"h":"Keep <a href=\"#party/hendrik\">Hendrik<\/a> tanking and <a href=\"#party/serena\">Serena<\/a> on <b>Omniheal<\/b>.","s":[38]},{"h":"Use <a href=\"#party/hero\">Gigagash<\/a> while both live.","s":[38]},{"h":"Take the <a href=\"#gear/accessory-ogler-s-digest\">Ogler&#x27;s digest<\/a> wish.","s":[38]},{"h":"Against <a href=\"#boss/abject-terror\">Abject terror<\/a> (7800 HP) and <a href=\"#boss/darkest-despair\">Darkest despair<\/a> (4200 HP, 50 turns), drop both low before killing either so neither gets revived with <b>Kazing<\/b>.","s":[38]},{"h":"Hit <a href=\"#boss/abject-terror\">Abject terror<\/a> with magic and <a href=\"#boss/darkest-despair\">Darkest despair<\/a> with physical attacks.","s":[38]}],"get_h":["<a href=\"#forge/book-kings-of-the-rings\">Kings of the Rings<\/a> - Cruel Crypt, lower level southeast","<a href=\"#forge/book-supreme-secrets-of-the-sword-of-light\">Supreme Secrets of the Sword of Light<\/a> - first wish from Drustan","<a href=\"#forge/book-eternal-elegance\">Eternal Elegance<\/a> - Hoarder&#x27;s Keep, Level 1 south","<a href=\"#gear/weapon-drustan-s-sword\">Drustan&#x27;s Sword<\/a> - Citadel of Spite, Level 3 exterior","<a href=\"#gear/headwear-erdwin-s-coronet\">Erdwin&#x27;s Coronet<\/a> - Citadel of Spite, Level 3 northwest","<a href=\"#forge/book-ye-manifold-methods-of-mighty-drustan\">Ye Manifold Methods of Mighty Drustan<\/a> - Citadel of Spite, under the Level 1 stairs"],"source":[{"t":"The Drustan Trials / Act III / Post Game / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-iii-post-game/the-drustan-trials"}]},"a3-echoes":{"steps":[{"h":"Learn <a href=\"#party/hero\">Pep Up<\/a> on the <a href=\"#party/hero\">Luminary<\/a>, <b>Lightning Thrust<\/b> on <a href=\"#party/jade\">Jade<\/a> and <b>Critical Claim<\/b> on <a href=\"#party/erik\">Erik<\/a> before you start levelling.","s":[39]},{"h":"Near a camp, defend in a battle until <a href=\"#party/erik\">Erik<\/a>, <a href=\"#party/jade\">Jade<\/a>, <a href=\"#party/sylvando\">Sylvando<\/a> and <a href=\"#party/rab\">Rab<\/a> are Pepped.","s":[39]},{"h":"End the battle with the <a href=\"#party/hero\">Luminary<\/a> using <a href=\"#party/hero\">Pep Up<\/a>.","s":[39]},{"h":"Save.","s":[39]},{"h":"Give <a href=\"#party/sylvando\">Sylvando<\/a> a <a href=\"#gear/item-pep-pip\">Pep pip<\/a>.","s":[39]},{"h":"Start a battle with the <a href=\"#party/hero\">Luminary<\/a>, <a href=\"#party/erik\">Erik<\/a>, <a href=\"#party/jade\">Jade<\/a> and <a href=\"#party/sylvando\">Sylvando<\/a>.","s":[39]},{"h":"Cast Haulellujah.","s":[39]},{"h":"Swap <a href=\"#party/erik\">Erik<\/a> for <a href=\"#party/rab\">Rab<\/a>.","s":[39]},{"h":"Re-Pep the <a href=\"#party/hero\">Luminary<\/a>.","s":[39]},{"h":"Have <a href=\"#party/sylvando\">Sylvando<\/a> use a <a href=\"#gear/item-pep-pip\">Pep pip<\/a> on <a href=\"#party/jade\">Jade<\/a>.","s":[39]},{"h":"Let the enemies act.","s":[39]},{"h":"Cast <b>Electro Light<\/b>.","s":[39]},{"h":"If no metal slimes appear, reload.","s":[39]},{"h":"If metal slimes appear, sleep them with <b>Dirge of Dundrasil<\/b>.","s":[39]},{"h":"Kill the sleeping metal slimes with <a href=\"#party/erik\">Critical Claim<\/a> and <a href=\"#party/jade\">Lightning Thrust<\/a> for 4-6 levels per run.","s":[39]},{"h":"In Harma trials one to three, open with <a href=\"#party/hero\">Sword Dance<\/a>, <a href=\"#party/hero\">Gigagash<\/a> or <a href=\"#party/jade\">Pink Tornado<\/a>.","s":[39]},{"h":"Finish groups with <b>Kathwack<\/b>, <b>Pearly Gates<\/b> or <b>Magic Burst<\/b>.","s":[39]},{"h":"In the Fourth Trial, use <a href=\"#party/erik\">Critical Claim<\/a> on each <b>Hardy hand<\/b> and <a href=\"#party/hendrik\">Gyrfalcon Slash<\/a> on the <b>Clangoustine<\/b>.","s":[39]},{"h":"Use <a href=\"#party/hero\">Sword Dance<\/a> on the <b>Red giant<\/b> solo.","s":[39]},{"h":"In the Final Trial, kill every enemy in the same round to stop reinforcements.","s":[39]},{"h":"Open with <a href=\"#party/hendrik\">Hendrik<\/a>&#x27;s <a href=\"#party/hendrik\">Gyrfalcon Slash<\/a> on the <b>Shadeshifter<\/b> and <a href=\"#party/rab\">Rab<\/a>&#x27;s <b>Pearly Gates<\/b>.","s":[39]},{"h":"In the Final Trial&#x27;s second battle, open with <a href=\"#party/veronica\">Channel Anger<\/a> and <a href=\"#party/serena\">Kaswooshle<\/a>.","s":[39]},{"h":"End the battle with <a href=\"#party/veronica\">Veronica<\/a>&#x27;s <b>Magic Burst<\/b>.","s":[39]},{"h":"In the third battle, have <a href=\"#party/erik\">Erik<\/a> use <a href=\"#party/erik\">Divide<\/a> and <a href=\"#party/sylvando\">Sylvando<\/a> use <a href=\"#party/sylvando\">That&#x27;s Amore<\/a>.","s":[39]},{"h":"Use <b>Critical Claim<\/b> on the <b>Pandora&#x27;s big bad box<\/b> while <a href=\"#party/sylvando\">Sylvando<\/a> uses <a href=\"#party/sylvando\">Gold Rush<\/a>.","s":[39]},{"h":"Stay within 14 actions.","s":[39]},{"h":"In the last battle, wear down the <b>Infernal serpent<\/b> (4000 HP) and <b>Manticore<\/b> (3600 HP).","s":[39]},{"h":"Use <a href=\"#party/hero\">Gigagash<\/a> and <a href=\"#party/jade\">Pink Tornado<\/a> so all fall together.","s":[39]},{"h":"Forge the <a href=\"#gear/weapon-legate-s-blade\">Legate&#x27;s blade<\/a> +3.","s":[39]},{"h":"Give the <a href=\"#gear/weapon-legate-s-blade\">Legate&#x27;s blade<\/a> to the High Hall monk to finish <a href=\"#quests/pointless-pride\">Pointless Pride<\/a> for Seeds of Skill.","s":[39]},{"h":"Equip <a href=\"#party/hendrik\">Hendrik<\/a> with two <a href=\"#gear/accessory-skull-ring\">Skull ring<\/a> +3 for full dark immunity.","s":[39]},{"h":"Forge gear to +3.","s":[39]},{"h":"Give <a href=\"#gear/item-elfin-elixir\">Elfin elixir<\/a>s to <a href=\"#party/veronica\">Veronica<\/a> and <a href=\"#party/serena\">Serena<\/a>.","s":[39]},{"h":"Against <a href=\"#boss/overweening-pride\">Overweening pride<\/a> (12000 HP, 50 turns), keep <a href=\"#party/hendrik\">Hendrik<\/a> on <b>Immense Defence<\/b> and <a href=\"#party/hendrik\">Forbearance<\/a>.","s":[39]},{"h":"Have <a href=\"#party/serena\">Serena<\/a> use <b>Omniheal<\/b> and <a href=\"#party/serena\">Divine Intervention<\/a> on <a href=\"#party/hendrik\">Hendrik<\/a>.","s":[39]},{"h":"Bring <a href=\"#party/erik\">Erik<\/a> with dual swords for <a href=\"#party/erik\">Divide<\/a> plus <a href=\"#party/erik\">Fatal Flash<\/a>.","s":[39]},{"h":"Use the <a href=\"#party/hero\">Luminary<\/a>&#x27;s <a href=\"#party/hero\">Gigagash<\/a> once reinforcements arrive.","s":[39]},{"h":"Spend Pep Powers before Disruptive Wave removes them: <b>Mighty Magic Burst<\/b> for 4000+, or <b>Yggdragon&#x27;s Blessing<\/b>.","s":[39]},{"h":"Use <b>Kerplunk<\/b> if most of the party is down.","s":[39]},{"h":"Keep the <a href=\"#gear/weapon-super-sword-of-light\">Super Sword of Light<\/a> on the <a href=\"#party/hero\">Luminary<\/a>.","s":[39]},{"h":"Stock MP items and <a href=\"#gear/item-yggdrasil-leaf\">Yggdrasil leaf<\/a>s.","s":[39]},{"h":"Fly <b>Cetacea<\/b> toward the dark star.","s":[39]},{"h":"On the <a href=\"#party/hero\">Luminary<\/a>&#x27;s first turn against <a href=\"#boss/calasmos\">Calasmos<\/a>, use the <a href=\"#gear/weapon-super-sword-of-light\">Super Sword of Light<\/a> from the inventory to strip the dark aura.","s":[39]},{"h":"Fight <a href=\"#boss/calasmos\">Calasmos<\/a> with <a href=\"#party/hendrik\">Hendrik<\/a> tanking, <a href=\"#party/serena\">Serena<\/a> on <b>Omniheal<\/b>, and the <a href=\"#party/hero\">Luminary<\/a> and <a href=\"#party/veronica\">Veronica<\/a> using <b>Gigagash<\/b> and <a href=\"#party/veronica\">Kaboomle<\/a> on the <a href=\"#boss/darkling\">Darkling<\/a>s.","s":[39]},{"h":"Cast <b>Magic Barrier<\/b> against Projectile of Darkness (250+ to the party).","s":[39]},{"h":"Spend your saved <a href=\"#gear/item-pep-pop\">Pep pop<\/a>s and <a href=\"#gear/item-elfin-elixir\">Elfin elixir<\/a>s here.","s":[39]}],"get_h":["<a href=\"#forge/book-shine-on-xenlon\">Shine On, Xenlon<\/a> - Wheel of Harma, Fourth Trial reward","<a href=\"#forge/book-a-hero-s-book-of-brilliant-weapons\">A Hero&#x27;s Book of Brilliant Weapons<\/a> - for taking all five of Drustan&#x27;s wishes","<a href=\"#gear/accessory-skull-ring\">Skull ring<\/a> - forge, or rare steal from <b>Infanticore<\/b>s in Dundrasil"],"source":[{"t":"Echoes of an Elusive Age / Act III / Post Game / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/act-iii-post-game/echoes-of-an-elusive-age"}]},"de-harma-secret":{"steps":[{"h":"Unlock the Secret Trial by finishing all of Drustan&#x27;s Trials and every other Wheel of Harma trial within its turn limit.","s":[40]},{"h":"Equip two <a href=\"#gear/accessory-catholicon-ring\">Catholicon ring<\/a>s each on the <a href=\"#party/hero\">Luminary<\/a> and <a href=\"#party/jade\">Jade<\/a>, and two <a href=\"#gear/accessory-venus-tear\">Venus&#x27; tear<\/a>s each on <a href=\"#party/erik\">Erik<\/a> and <a href=\"#party/sylvando\">Sylvando<\/a>.","s":[40]},{"h":"Give <a href=\"#party/erik\">Erik<\/a> two <a href=\"#gear/weapon-hunter-s-moon\">Hunter&#x27;s moon<\/a>s.","s":[40]},{"h":"Put <a href=\"#gear/accessory-meteorite-bracer\">Meteorite bracer<\/a>s on <a href=\"#party/serena\">Serena<\/a> and <a href=\"#party/hendrik\">Hendrik<\/a> so they act before <a href=\"#party/veronica\">Veronica<\/a>.","s":[40]},{"h":"Pep Up <a href=\"#party/veronica\">Veronica<\/a> and <a href=\"#party/serena\">Serena<\/a> before entering the trial.","s":[40]},{"h":"In round 1, have <a href=\"#party/serena\">Serena<\/a> start <b>Mighty Magic Burst<\/b>.","s":[40]},{"h":"Have <a href=\"#party/hendrik\">Hendrik<\/a> throw an <a href=\"#gear/item-elfin-elixir\">Elfin elixir<\/a> to <a href=\"#party/veronica\">Veronica<\/a>.","s":[40]},{"h":"Have <a href=\"#party/veronica\">Veronica<\/a> finish with <b>Magic Burst<\/b>.","s":[40]},{"h":"If the turn order goes wrong or the <b>Archbashop<\/b> casts <b>Bounce<\/b>, flee or reload.","s":[40]},{"h":"Retry round 1.","s":[40]},{"h":"In round 2, cast <a href=\"#party/rab\">Infinite Wisdom<\/a> on <a href=\"#party/rab\">Rab<\/a> first.","s":[40]},{"h":"Use <a href=\"#party/rab\">Kacrackle<\/a> every turn against <a href=\"#boss/boodica\">Boodica<\/a> without recasting the buff.","s":[40]},{"h":"If <a href=\"#party/rab\">Rab<\/a> gets low, especially once the doppelganger appears, heal him with <b>Fullheal<\/b> or a <a href=\"#gear/item-yggdrasil-dew\">Yggdrasil dew<\/a>.","s":[40]},{"h":"In round 3, have <a href=\"#party/erik\">Erik<\/a> use <a href=\"#party/erik\">Divide<\/a> while <a href=\"#party/sylvando\">Sylvando<\/a> casts <b>Oomphle<\/b> on him.","s":[40]},{"h":"Use <a href=\"#party/erik\">Double Down<\/a> aimed at the <a href=\"#boss/coralossus\">Coralossus<\/a>.","s":[40]},{"h":"If the <a href=\"#boss/coralossus\">Coralossus<\/a> uses <a href=\"#party/hendrik\">Forbearance<\/a>, have <a href=\"#party/sylvando\">Sylvando<\/a> use <a href=\"#party/sylvando\">Gold Rush<\/a> (about 300 each) while <a href=\"#party/erik\">Erik<\/a> keeps using <a href=\"#party/erik\">Double Down<\/a>.","s":[40]},{"h":"In round 4, attack <a href=\"#boss/grand-master-pang\">Grand Master Pang<\/a> nonstop, healing only with the <a href=\"#party/hero\">Luminary<\/a>&#x27;s <a href=\"#party/hero\">Omniheal<\/a>.","s":[40]},{"h":"Use <b>Re-Vamp<\/b> once with <a href=\"#party/jade\">Jade<\/a> in her spellcasting stance.","s":[40]},{"h":"Keep <b>Multifeet<\/b> and <a href=\"#party/hero\">Sword Dance<\/a> on Pang when she summons an <b>Equinox<\/b> and a <b>Godsteed<\/b>.","s":[40]},{"h":"Brace on the turn after her second power-up.","s":[40]},{"h":"Once Pang falls, clear the horses with <a href=\"#party/jade\">Pink Tornado<\/a> and <a href=\"#party/hero\">Gigagash<\/a> or <b>Quadraslash<\/b>.","s":[40]},{"h":"Finish in under 50 moves for extra Super Seeds of Defence, since the reward cannot be earned again.","s":[40]}],"get_h":[],"source":[{"t":"Wheel of Harma's Secret Trial / Definitive Edition Endgame / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/definitive-edition-endgame/wheel-of-harmas-secret-trial"}]},"de-timewyrm":{"steps":[{"h":"Unlock the fight by defeating the <a href=\"#boss/end-of-time\">End of Time<\/a> in the Deepest Recesses of the Past.","s":[41]},{"h":"If fighting without the Pep Power trick, farm only <a href=\"#gear/item-seed-of-defence\">Seed of defence<\/a>, <a href=\"#gear/item-seed-of-life\">Seed of life<\/a> and <a href=\"#gear/item-seed-of-strength\">Seed of strength<\/a>, aiming for 999 HP, 999 Attack and about 500 defence.","s":[41]},{"h":"Buy a stack of <a href=\"#gear/item-pep-pop\">Pep pop<\/a>s at the rebuilt Cobblestone shop, about 20 split across the party.","s":[41]},{"h":"Buy <a href=\"#gear/item-elfin-elixir\">Elfin elixir<\/a>s at the Octagonia Casino; <b>Magic Burst<\/b> deals about three times <a href=\"#party/veronica\">Veronica<\/a>&#x27;s MP, and each of the two parts has 20,000 HP.","s":[41]},{"h":"Bring the <a href=\"#party/hero\">Luminary<\/a>, <a href=\"#party/erik\">Erik<\/a>, <a href=\"#party/veronica\">Veronica<\/a> and <a href=\"#party/rab\">Rab<\/a>.","s":[41]},{"h":"Equip <a href=\"#gear/accessory-catholicon-ring\">Catholicon ring<\/a>s against the sleep and confusion attacks.","s":[41]},{"h":"Pep Up all four in a normal battle by defending, swapping each one out once Pepped to keep the state.","s":[41]},{"h":"Fly <b>Cetacea<\/b> into the rift above the Tower of Lost Time.","s":[41]},{"h":"Open the fight with <b>Yggdragon&#x27;s Blessing<\/b> which makes your characters invulnerable to damage.","s":[41]},{"h":"When the Blessing icon starts flashing, throw a <a href=\"#gear/item-pep-pop\">Pep pop<\/a> so you can cast it again; it only lasts 2-3 turns.","s":[41]},{"h":"Hit the <a href=\"#boss/timewyrm\">Timewyrm&#x27;s tail<\/a> first with <b>Magic Burst<\/b>, refilling <a href=\"#party/veronica\">Veronica<\/a> with <a href=\"#gear/item-elfin-elixir\">Elfin elixir<\/a>s; expect Disruptive Wave at every phase switch.","s":[41]},{"h":"When the main body casts its double-MP mist, keep using <b>Magic Burst<\/b> but expect half damage per cast.","s":[41]},{"h":"In the final phase, if either part gets Pepped, strip it with <a href=\"#party/rab\">Rab<\/a>&#x27;s <a href=\"#party/rab\">Rake &#x27;n&#x27; Break<\/a> or <a href=\"#party/rab\">Clear Your Mind<\/a> to stop <b>Malicious Magic Burst<\/b> and Blackest Mark.","s":[41]},{"h":"If fighting normally, reapply <b>Kabuff<\/b>, <b>Magic Barrier<\/b> and <b>Insulatle<\/b> each phase.","s":[41]},{"h":"If fighting normally, bring the <a href=\"#party/hero\">Luminary<\/a> and <a href=\"#party/serena\">Serena<\/a> for <b>Omniheal<\/b>.","s":[41]},{"h":"If fighting normally, attack with <a href=\"#party/hero\">Sword Dance<\/a>.","s":[41]},{"h":"Use the <b>Sands of Lost Time<\/b> to refight it if you want the Accolades for winning in under 70 or under 50 turns.","s":[41]}],"get_h":["<a href=\"#gear/armor-hare-raising-suit\">Hare-raising suit<\/a> - Timewyrm reward, auto-revives Jade, final costume","<b>Sands of Lost Time<\/b> - Timewyrm reward, lets you refight it"],"source":[{"t":"Timewyrm / Definitive Edition Endgame / Walkthrough (GamerGuides)","u":"https://www.gamerguides.com/dragon-quest-xi-echoes-of-an-elusive-age-definitive-edition/guide/walkthrough/definitive-edition-endgame/timewyrm"}]}};
